function renderSaasClients(rows){
  const target=document.getElementById("saasClientsList"),tabs=['Información general','Plan y suscripción','Usuarios','Funcionalidades','Límites','Pagos','Actividad','Integraciones','Historial de cambios'];target.innerHTML=rows.length?rows.map(c=>`<article class="saas-client-card" data-client-id="${safeUser(c.id)}"><div class="saas-client-head"><div><span class="person">${safeUser(c.name)}</span><div class="detail">@${safeUser(c.username||'sin usuario')} · Alta ${formatBillingDate(c.created_at)} · ${Number(c.associated_users||0)} usuarios asociados · Último pago ${formatBillingDate(c.last_payment)}</div></div><span class="subscription-status ${c.status==='active'||c.status==='trial'?'':c.status==='suspended'?'warn':'stop'}">${{trial:'Prueba',active:'Activo',suspended:'Suspendido',cancelled:'Archivado'}[c.status]||safeUser(c.status)}</span></div><div class="saas-client-actions client-admin-tabs">${tabs.map((label,index)=>`<button class="secondary clientTab" data-tab="${index}">${label}</button>`).join('')}</div><p class="detail clientTabSummary">Ficha administrativa completa de la clínica.</p><div class="saas-client-grid"><label>Clínica / odontólogo<input class="clientName" value="${safeUser(c.name)}"></label><label>Correo<input class="clientEmail" type="email" value="${safeUser(c.email)}"></label><label>Teléfono<input class="clientPhone" value="${safeUser(c.phone)}"></label><label>Plan<select class="clientPlan"><option value="basic">Básico</option><option value="medium">Intermedio</option><option value="premium">Premium</option></select></label><label>Precio mensual personalizado<input class="clientPrice" type="number" min="0" value="${Number(c.monthly_price||0)}"></label><label>Descuento %<input class="clientDiscount" type="number" min="0" max="100" value="${Number(c.discount_percent||0)}"></label><label>Promoción hasta<input class="clientPromotionExpiry" type="date" value="${safeUser(c.promotion_expires_at||'')}"></label><label>Suscripción<select class="clientSubscription"><option value="active">Activa</option><option value="past_due">Vencida</option><option value="pending">Pendiente</option><option value="suspended">Suspendida</option><option value="cancelled">Cancelada</option></select></label><label>Próximo vencimiento<input class="clientRenewal" type="date" value="${safeUser(c.renews_at||'')}"></label><label>Cuenta<select class="clientStatus"><option value="trial">Prueba</option><option value="active">Activa</option><option value="suspended">Suspendida</option><option value="cancelled">Archivada</option></select></label><label style="grid-column:1/-1">Nota comercial<input class="clientCommercialNote" value="${safeUser(c.commercial_note||'')}" placeholder="Motivo del precio, descuento o promoción"></label></div><div class="saas-client-actions"><button class="primary saveSaasClient">Guardar cambios</button><button class="secondary clientFeatures">Administrar funciones y límites</button><button class="secondary supportClient" data-mode="admin">Soporte como Admin</button><button class="secondary supportClient" data-mode="odontologo">Soporte como Odontólogo</button><button class="secondary previewClientImpact">Ver datos y dependencias</button><button class="secondary suspendClient">Suspender</button><button class="secondary reactivateClient">Reactivar</button><button class="secondary archiveClient">Archivar</button><button class="secondary requestClientDeletion">Solicitar eliminación</button></div><div class="client-features-panel" hidden></div></article>`).join(""):'<p class="detail">No hay clientes cargados.</p>';
  rows.forEach(c=>{const row=target.querySelector(`[data-client-id="${CSS.escape(c.id)}"]`);row.querySelector('.clientPlan').value=c.plan||'basic';row.querySelector('.clientSubscription').value=c.subscription_status||'active';row.querySelector('.clientStatus').value=c.status||'active';row.querySelectorAll('.clientTab').forEach(button=>button.onclick=()=>openClientAdminTab(row,Number(button.dataset.tab),c));});target.querySelectorAll('.saveSaasClient').forEach(button=>button.onclick=()=>saveSaasClient(button.closest('[data-client-id]')));target.querySelectorAll('.clientFeatures').forEach(button=>button.onclick=()=>loadClientFeatures(button.closest('[data-client-id]')));target.querySelectorAll('.supportClient').forEach(button=>button.onclick=()=>enterClientSupport(button.closest('[data-client-id]').dataset.clientId,button.dataset.mode));target.querySelectorAll('.previewClientImpact').forEach(button=>button.onclick=()=>clientLifecycle(button.closest('[data-client-id]').dataset.clientId,'preview'));target.querySelectorAll('.suspendClient').forEach(button=>button.onclick=()=>clientLifecycle(button.closest('[data-client-id]').dataset.clientId,'suspend'));target.querySelectorAll('.reactivateClient').forEach(button=>button.onclick=()=>clientLifecycle(button.closest('[data-client-id]').dataset.clientId,'reactivate'));target.querySelectorAll('.archiveClient').forEach(button=>button.onclick=()=>clientLifecycle(button.closest('[data-client-id]').dataset.clientId,'archive'));target.querySelectorAll('.requestClientDeletion').forEach(button=>button.onclick=()=>clientLifecycle(button.closest('[data-client-id]').dataset.clientId,'request_deletion'));
}
function openClientAdminTab(row,index,client){const summaries=[`Contacto: ${client.email||'sin correo'} · ${client.phone||'sin teléfono'}`,`Plan ${client.plan==='medium'?'Intermedio':client.plan} · Precio ${formatMoney(client.monthly_price||0)} · Descuento ${Number(client.discount_percent||0)}%`,`Usuarios asociados: ${Number(client.associated_users||0)}. Administralos desde Usuarios y administradores.`,`Abrí el administrador de funciones para establecer excepciones individuales.`,`Los límites temporales admiten fecha de vencimiento y motivo obligatorio.`,`Último pago: ${formatBillingDate(client.last_payment)}. Consultá el historial en Cobros y facturación.`,`La actividad administrativa se muestra dentro de Funcionalidades y límites.`,`WhatsApp y servicios externos permanecen aislados para esta clínica.`,`Todos los cambios quedan vinculados al Superadmin responsable.`];row.querySelector('.clientTabSummary').textContent=summaries[index]||summaries[0];if([3,4,6,7,8].includes(index)){const panel=row.querySelector('.client-features-panel');if(panel.hidden)loadClientFeatures(row)}if(index===2)document.querySelector('[data-view="users"]')?.scrollIntoView({behavior:'smooth'});}
async function loadClientFeatures(row){const panel=row.querySelector('.client-features-panel');if(!panel.hidden){panel.hidden=true;return}panel.hidden=false;panel.innerHTML='<p class="detail">Cargando funcionalidades…</p>';const response=await fetch(saasEndpoint(`/api/saas/clients/${encodeURIComponent(row.dataset.clientId)}/features`)),data=await response.json();if(!response.ok){panel.textContent=data.error||'No se pudo cargar.';return}const labels={basic:'Básico',medium:'Intermedio',premium:'Premium'};panel.innerHTML=`<div class="toolbar"><div><h3>Funcionalidades y límites</h3><p class="detail">Plan ${labels[data.client.plan]||data.client.plan} · Pacientes ilimitados · WhatsApp ${safeUser(data.whatsapp.status||'desconectado')}</p></div><button class="primary saveClientFeatures">Guardar excepciones</button></div>${data.features.map(f=>`<div class="client-feature-row" data-client-feature="${safeUser(f.feature_key)}"><div><b>${safeUser(f.name)}</b><small style="display:block;color:var(--muted)">${safeUser(f.description)} · ${f.source==='client_override'?'Excepción individual':f.enabled?'Incluida por plan':'No incluida en el plan'}</small></div><select><option value="inherit" ${f.overrideEnabled===null?'selected':''}>Heredar (${f.planEnabled?'habilitada':'deshabilitada'})</option><option value="on" ${f.overrideEnabled===true?'selected':''}>Habilitar</option><option value="off" ${f.overrideEnabled===false?'selected':''}>Deshabilitar</option></select><div>${f.limit_type&&f.limit_type!=='boolean'?`<input class="clientFeatureLimit" type="number" min="0" value="${f.override_limit??''}" placeholder="Límite del plan: ${f.plan_limit??'sin límite'}"><input class="clientFeatureExpiry" type="date" value="${safeUser(f.limit_expires_at||'')}" title="Vencimiento de excepción">`:'<span class="detail">Sin límite numérico</span>'}</div></div>`).join('')}<div class="plan-note"><b>Actividad reciente</b><br>${(data.activity||[]).slice(0,5).map(a=>`${safeUser(a.action)} · ${new Date(a.created_at).toLocaleString('es-AR')}`).join('<br>')||'Sin actividad administrativa reciente.'}</div>`;panel.querySelector('.saveClientFeatures').onclick=()=>saveClientFeatures(row,panel);}
async function saveClientFeatures(row,panel){const reason=prompt('Motivo de la excepción individual:','Ajuste comercial autorizado');if(reason===null||!reason.trim())return;const overrides=[...panel.querySelectorAll('[data-client-feature]')].map(item=>({key:item.dataset.clientFeature,enabled:item.querySelector('select').value==='inherit'?null:item.querySelector('select').value==='on',limit:item.querySelector('.clientFeatureLimit')?.value??null,expiresAt:item.querySelector('.clientFeatureExpiry')?.value||null,reason:reason.trim()})),response=await fetch(saasEndpoint(`/api/saas/clients/${encodeURIComponent(row.dataset.clientId)}/features`),{method:'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify({overrides,reason})}),data=await response.json();if(!response.ok)return alert(data.error||'No se pudo guardar.');alert('Funcionalidades y límites actualizados con auditoría.');panel.hidden=true;await Promise.all([loadAdminAudit(),loadClientFeatures(row),loadMonitoring()]);}
async function clientLifecycle(clientId,action){const labels={suspend:'suspender el acceso',reactivate:'reactivar la clínica',archive:'archivar la clínica',request_deletion:'registrar una solicitud de eliminación'},preview=await fetch(saasEndpoint(`/api/saas/clients/${encodeURIComponent(clientId)}/lifecycle`),{method:'POST',headers:{'content-type':'text/plain'},body:JSON.stringify({action:'preview'})}),impact=await preview.json();if(!preview.ok)return alert(impact.error||'No se pudo revisar la clínica.');const message=`${impact.clientName}\n\nRegistros clínicos: ${impact.impact.consultations}\nUsuarios: ${impact.impact.users}\nFacturas: ${impact.impact.invoices}\nPagos: ${impact.impact.payments}\n\n${impact.impact.retentionNotice}`;if(action==='preview')return alert(message);if(!confirm(`${message}\n\n¿Confirmás ${labels[action]}?`))return;const response=await fetch(saasEndpoint(`/api/saas/clients/${encodeURIComponent(clientId)}/lifecycle`),{method:'POST',headers:{'content-type':'text/plain'},body:JSON.stringify({action})}),data=await response.json();if(!response.ok)return alert(data.error||'No se pudo completar.');alert(action==='request_deletion'?'Solicitud registrada para revisión. No se eliminó ningún dato.':'Acción registrada correctamente.');await Promise.all([loadSaasClients(),loadClinics(),loadSaasDashboard(),loadAdminAudit(),loadMonitoring()]);}
