async function saveSaasClient(row){const payload={name:row.querySelector('.clientName').value,email:row.querySelector('.clientEmail').value,phone:row.querySelector('.clientPhone').value,plan:row.querySelector('.clientPlan').value,monthlyPrice:row.querySelector('.clientPrice').value,discountPercent:row.querySelector('.clientDiscount').value,promotionExpiresAt:row.querySelector('.clientPromotionExpiry').value,commercialNote:row.querySelector('.clientCommercialNote').value,subscriptionStatus:row.querySelector('.clientSubscription').value,renewsAt:row.querySelector('.clientRenewal').value,status:row.querySelector('.clientStatus').value},response=await fetch(saasEndpoint(`/api/saas/clients/${encodeURIComponent(row.dataset.clientId)}`),{method:"PATCH",headers:{"content-type":"text/plain"},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)return alert(data.error||"No se pudo guardar.");await Promise.all([loadSaasClients(document.getElementById("saasClientSearch").value),loadSaasDashboard(),loadMonitoring(),loadAdminAudit()]);}
async function enterClientSupport(clientId,mode){const client=saasClients.find(x=>x.id===clientId),reason=prompt(`Motivo del acceso de soporte a ${client?.name||'la clínica'}:`,`Soporte solicitado por el cliente`);if(reason===null)return;const response=await fetch(saasEndpoint("/api/saas/support-access"),{method:"POST",headers:{"content-type":"text/plain"},body:JSON.stringify({clientId,mode,reason})}),data=await response.json();if(!response.ok)return alert(data.error||"No se pudo iniciar el acceso.");sessionStorage.setItem("odontocentroSupportClient",clientId);sessionStorage.setItem("odontocentroSupportClientName",data.client.name);const user=JSON.parse(sessionStorage.getItem("odontocentroProfessional")||"{}");document.getElementById("superAdminMode").value=mode;await switchSuperAdminMode(mode,user);const context=document.getElementById('context-title');if(context)context.textContent=`Soporte · ${data.client.name}`;}
