function renderClinics(rows){const body=document.getElementById('clinicTableBody');body.innerHTML=rows.length?rows.map(c=>`<tr data-clinic-id="${safeUser(c.id)}"><td><b>${safeUser(c.name)}</b><small>${safeUser(c.city||'Sin localidad')} · ${safeUser(c.email)}</small></td><td>${safeUser(c.owner_name||c.contact_name||'—')}<small>${safeUser(c.tax_id||'Sin CUIT/CUIL')}</small></td><td><b>${Number(c.associated_users||0)} de ${Number(c.max_users||0)}</b><small>${safeUser(c.username||'Sin administrador')}</small></td><td><span class="tag">${clinicPlanLabel(c.plan)}</span></td><td><span class="status-pill ${c.status==='active'||c.status==='trial'?'active':c.status==='suspended'?'blocked':'deleted'}">${clinicStatusLabel(c.status)}</span></td><td>${formatBillingDate(c.created_at)}</td><td>${formatBillingDate(c.status==='trial'?c.trial_ends_at:c.renews_at)}</td><td><div class="clinic-actions"><button class="secondary clinicDetails">Detalles</button><button class="secondary clinicEdit">Editar</button><button class="secondary clinicUsers">Usuarios</button><button class="secondary clinicPlan">Cambiar plan</button>${c.status==='suspended'?'<button class="primary clinicActivate">Activar</button>':'<button class="warning-action clinicSuspend">Suspender</button>'}${c.status==='cancelled'?'':'<button class="danger-action clinicArchive">Archivar</button>'}</div></td></tr>`).join(''):'<tr><td colspan="8">No hay consultorios para estos filtros.</td></tr>';rows.forEach(c=>{const row=body.querySelector(`[data-clinic-id="${CSS.escape(c.id)}"]`);row.querySelector('.clinicDetails').onclick=()=>alert(`${c.name}\n\nPropietario: ${c.owner_name||c.contact_name||'—'}\nCorreo: ${c.email}\nTeléfono: ${c.phone||'—'}\nWhatsApp: ${c.whatsapp||'—'}\nDirección: ${[c.address,c.city,c.province,c.country].filter(Boolean).join(', ')||'—'}\nZona horaria: ${c.timezone}\nMoneda: ${c.default_currency}\nUsuarios: ${c.associated_users} de ${c.max_users}`);row.querySelector('.clinicEdit').onclick=()=>openClinicDialog({clinic:c});row.querySelector('.clinicPlan').onclick=()=>openClinicDialog({clinic:c,focusPlan:true});row.querySelector('.clinicUsers').onclick=()=>manageClinicUsers(c);row.querySelector('.clinicSuspend')?.addEventListener('click',()=>clientLifecycle(c.id,'suspend'));row.querySelector('.clinicActivate')?.addEventListener('click',()=>clientLifecycle(c.id,'reactivate'));row.querySelector('.clinicArchive')?.addEventListener('click',()=>clientLifecycle(c.id,'archive'));});}
function manageClinicUsers(clinic){document.querySelector('[data-view="users"]')?.click();const search=document.getElementById('userSearch');if(search)search.value=clinic.name;loadUsersV2();}
function planCatalogItem(plan){return saasPlans.find(item=>item.plan===plan)}
async function loadClinicPlanCatalog(selected='basic'){if(!saasPlans.length){const response=await fetch(saasEndpoint('/api/saas/plans')),rows=await response.json();if(!response.ok)throw new Error(rows.error||'No se pudo cargar el catálogo de planes.');saasPlans=rows}const select=document.getElementById('clinicPlan'),active=saasPlans.filter(item=>item.price_active!==0&&item.configuration);select.innerHTML=active.map(item=>`<option value="${safeUser(item.plan)}">${safeUser(item.name)}</option>`).join('');select.value=active.some(item=>item.plan===selected)?selected:(active[0]?.plan||'');updateClinicPlanDefaults()}
function updateClinicPlanDefaults(){const plan=document.getElementById('clinicPlan').value,item=planCatalogItem(plan),config=item?.configuration,max=document.getElementById('clinicMaxUsers'),preview=document.getElementById('clinicPlanPreview');max.value=config?.maxUsers||0;max.readOnly=true;if(!config){preview.textContent='Este plan no está activo o no tiene una configuración válida.';return}const moduleLabels=Object.fromEntries(SYSTEM_FUNCTIONS),features=(config.features||[]).map(f=>f.name),benefits=(config.benefits||[]);preview.innerHTML=`<h4>${safeUser(config.name)} · asignación automática</h4><div class="plan-preview-metrics"><span>Precio mensual<b>${formatMoneyMinor(config.monthlyUsdCents,'USD')}</b></span><span>Equivalente ARS<b>${config.arsEquivalentMinor?formatMoneyMinor(config.arsEquivalentMinor,'ARS'):'Sin cotización'}</b></span><span>Precio anual<b>${config.annualUsdCents?formatMoneyMinor(config.annualUsdCents,'USD'):'No configurado'}</b></span><span>Usuarios máximos<b>${Number(config.maxUsers)}</b></span></div><small>Facturación mensual · Cotización ${config.fxQuoteId?'vigente registrada':'no disponible'} · El precio se toma del catálogo central.</small><ul>${(features.length?features:benefits).slice(0,8).map(value=>`<li>${safeUser(value)}</li>`).join('')}</ul><small>Módulos: ${(config.modules||[]).map(key=>safeUser(moduleLabels[key]||key)).join(' · ')||'Sin módulos configurados'}</small>`;}
function toggleTrialEnd(){const trial=document.getElementById('clinicStatus').value==='trial',field=document.getElementById('clinicTrialEnds');field.disabled=!trial;if(trial&&!field.value){const next=new Date();next.setDate(next.getDate()+14);field.value=next.toISOString().slice(0,10);}}
async function openClinicDialog({source='clinics',clinic=null,focusPlan=false}={}){clinicDialogSource=source;clinicEditingRecord=clinic;const dialog=document.getElementById('clinicDialog');dialog.hidden=false;document.getElementById('clinicDialogTitle').textContent=clinic?'Editar consultorio':'Crear nuevo consultorio';document.getElementById('clinicEditId').value=clinic?.id||'';document.getElementById('clinicIdempotencyKey').value=clinic?'':crypto.randomUUID();const values={clinicName:clinic?.name||'',clinicOwner:clinic?.owner_name||clinic?.contact_name||'',clinicTaxId:clinic?.tax_id||'',clinicEmail:clinic?.email||'',clinicPhone:clinic?.phone||'',clinicWhatsapp:clinic?.whatsapp||'',clinicAddress:clinic?.address||'',clinicCity:clinic?.city||'',clinicProvince:clinic?.province||'',clinicCountry:clinic?.country||'Argentina',clinicStatus:clinic?.status==='cancelled'?'suspended':clinic?.status||'trial',clinicStartedAt:(clinic?.started_at||new Date().toISOString()).slice(0,10),clinicTrialEnds:clinic?.trial_ends_at||'',clinicMaxUsers:clinic?.max_users||2,clinicTimezone:clinic?.timezone||'America/Argentina/Buenos_Aires',clinicCurrency:clinic?.default_currency||'ARS',clinicRenewsAt:clinic?.renews_at||''};Object.entries(values).forEach(([id,value])=>{const el=document.getElementById(id);if(el)el.value=value});try{await loadClinicPlanCatalog(clinic?.plan||'basic')}catch(error){document.getElementById('clinicMessage').textContent=error.message}['clinicAdminFirstName','clinicAdminLastName','clinicAdminUsername','clinicAdminEmail','clinicAdminPassword'].forEach(id=>document.getElementById(id).value='');document.getElementById('clinicAdminSection').hidden=!!clinic;document.getElementById('saveClinic').textContent=clinic?'Guardar cambios':'Crear consultorio y administrador';document.getElementById('clinicMessage').textContent=source==='user'?'Cuando termine, volverás al usuario con este consultorio seleccionado.':'';toggleTrialEnd();if(focusPlan)setTimeout(()=>document.getElementById('clinicPlan').focus(),50);else setTimeout(()=>document.getElementById('clinicName').focus(),50);}
function closeClinicDialog(){document.getElementById('clinicDialog').hidden=true;}
async function saveClinic(){
  const message=document.getElementById('clinicMessage'),button=document.getElementById('saveClinic'),id=document.getElementById('clinicEditId').value,payload={name:document.getElementById('clinicName').value.trim(),ownerName:document.getElementById('clinicOwner').value.trim(),taxId:document.getElementById('clinicTaxId').value.trim(),email:document.getElementById('clinicEmail').value.trim(),phone:document.getElementById('clinicPhone').value.trim(),whatsapp:document.getElementById('clinicWhatsapp').value.trim(),address:document.getElementById('clinicAddress').value.trim(),city:document.getElementById('clinicCity').value.trim(),province:document.getElementById('clinicProvince').value.trim(),country:document.getElementById('clinicCountry').value.trim(),plan:document.getElementById('clinicPlan').value,status:document.getElementById('clinicStatus').value,startedAt:document.getElementById('clinicStartedAt').value,trialEndsAt:document.getElementById('clinicTrialEnds').value,timezone:document.getElementById('clinicTimezone').value,currency:document.getElementById('clinicCurrency').value,renewsAt:document.getElementById('clinicRenewsAt').value,idempotencyKey:document.getElementById('clinicIdempotencyKey').value};
  if(!id)Object.assign(payload,{adminFirstName:document.getElementById('clinicAdminFirstName').value.trim(),adminLastName:document.getElementById('clinicAdminLastName').value.trim(),username:document.getElementById('clinicAdminUsername').value.trim(),adminEmail:(document.getElementById('clinicAdminEmail').value||payload.email).trim(),password:document.getElementById('clinicAdminPassword').value});
  const missing=!payload.name||!payload.ownerName||!payload.email||(!id&&(!payload.adminFirstName||!payload.username||!payload.adminEmail||payload.password.length<8));if(missing){message.textContent='Completá los campos obligatorios y una contraseña inicial de al menos 8 caracteres.';return}if(payload.status==='trial'&&!payload.trialEndsAt){message.textContent='Indicá el vencimiento del período de prueba.';return}
  button.disabled=true;button.setAttribute('aria-busy','true');message.textContent=id?'Guardando cambios…':'Guardando el consultorio en la base de datos…';
  try{
    if(id&&clinicEditingRecord?.plan!==payload.plan){const previewResponse=await fetch(saasEndpoint(`/api/saas/clients/${encodeURIComponent(id)}/subscription/preview`),{method:'POST',headers:{'content-type':'text/plain'},body:JSON.stringify({targetPlan:payload.plan})}),preview=await previewResponse.json();if(!previewResponse.ok)throw new Error(preview.error||'No se pudo preparar el cambio de plan.');const warning=preview.warnings?.length?`\n\nADVERTENCIAS:\n${preview.warnings.join('\n')}\n${preview.downgradePolicy}`:'';if(!confirm(`Cambio de plan para ${preview.clientName}\n\n${clinicPlanLabel(preview.fromPlan)} → ${clinicPlanLabel(preview.toPlan)}\nNuevo valor: ${formatMoneyMinor(preview.after.monthlyUsdCents,'USD')} por mes\nEquivalente: ${preview.after.arsEquivalentMinor?formatMoneyMinor(preview.after.arsEquivalentMinor,'ARS'):'sin cotización'}\nUsuarios permitidos: ${preview.after.maxUsers}${warning}\n\nLas facturas y pagos anteriores se conservarán. ¿Confirmás?`))return;payload.confirmPlanChange=true;payload.planPreviewToken=preview.previewToken;payload.planChangeReason='Cambio confirmado desde NEXORA Control Center'}const endpoint=id?`/api/saas/clients/${encodeURIComponent(id)}`:'/api/saas/clients',response=await fetch(saasEndpoint(endpoint),{method:id?'PATCH':'POST',headers:{'content-type':'text/plain'},body:JSON.stringify(payload)}),data=await response.json().catch(()=>({error:`El servidor respondió ${response.status} sin un detalle válido.`}));
    if(!response.ok)throw new Error(data.error||'No se pudo guardar el consultorio.');if(!id&&(!data.id||data.persistenceConfirmed!==true))throw new Error('El servidor no confirmó la persistencia del consultorio.');
    document.getElementById('clinicSearch').value='';document.getElementById('clinicPlanFilter').value='';document.getElementById('clinicStatusFilter').value='';
    const refresh=await Promise.allSettled([loadClinics(1),loadSaasClients(),loadSaasDashboard(),loadClinicOptions(data.id||id),loadAuditCenter()]),refreshFailed=refresh.some(item=>item.status==='rejected');
    if(clinicDialogSource==='user'&&!id){const selector=document.getElementById('editUserClient'),option=[...selector.options].find(item=>item.value===data.id);if(!option)throw new Error('El consultorio se guardó, pero su estado no permite asignarle usuarios. Activá la cuenta e intentá nuevamente.');selector.value=data.id;showSelectedUserClinicPlan();}
    message.textContent=id?'Consultorio actualizado y verificado.':refreshFailed?'Consultorio guardado. Algunos paneles no pudieron actualizarse y se reintentarán al volver a abrirlos.':'Consultorio creado, persistido y disponible para asignar usuarios.';
    setTimeout(closeClinicDialog,refreshFailed?1600:700);
  }catch(error){console.error('No se pudo guardar el consultorio',error);message.textContent=error.message||'No se pudo guardar. Revisá la conexión y volvé a intentar; los datos permanecen en el formulario.';}
  finally{button.disabled=false;button.removeAttribute('aria-busy');}
}
function parseArgentineMinor(value){let text=String(value??'').trim().replace(/\s|\$|US\$/gi,'');if(!text||text.startsWith('-'))return null;if(text.includes(','))text=text.replace(/\./g,'').replace(',','.');else if((text.match(/\./g)||[]).length>1||/^\d+\.\d{3}$/.test(text))text=text.replace(/\./g,'');const match=text.match(/^(\d+)(?:\.(\d{1,2}))?$/);if(!match)return null;const minor=Number(match[1])*100+Number((match[2]||'').padEnd(2,'0'));return Number.isSafeInteger(minor)?minor:null}
function formatMoneyMinor(value,currency='ARS'){const minor=Number(value);return formatMoney(Number.isFinite(minor)?minor/100:0,currency)}
function invoiceStatusLabel(status){return {paid:'Pagada',partial:'Pago parcial',pending:'Pendiente',past_due:'Vencida'}[status]||status}
function paymentStatusLabel(status){return {confirmed:'Confirmado',pending:'Pendiente',rejected:'Rechazado'}[status]||status}
function addInvoiceLine(item={}){const body=document.getElementById('invoiceItems');if(!body)return;const row=document.createElement('tr');row.className='invoice-item';row.innerHTML=`<td><input class="line-description" maxlength="180" value="${safeUser(item.description||'Suscripción mensual')}" aria-label="Concepto"></td><td><input class="line-quantity" inputmode="decimal" value="${safeUser(item.quantity||'1')}" aria-label="Cantidad"></td><td><input class="line-unit billing-money-input" inputmode="decimal" value="${safeUser(item.unitPrice||'0,00')}" aria-label="Precio unitario"></td><td class="line-subtotal">$ 0,00</td><td><button class="secondary remove-invoice-line" type="button" aria-label="Quitar concepto">×</button></td>`;body.append(row);row.querySelectorAll('input').forEach(input=>input.addEventListener('input',updateInvoiceCalculation));row.querySelector('.remove-invoice-line').onclick=()=>{if(body.children.length>1)row.remove();updateInvoiceCalculation()};updateInvoiceCalculation()}
function invoiceFormItems(){return [...document.querySelectorAll('#invoiceItems .invoice-item')].map(row=>{const quantityText=row.querySelector('.line-quantity').value.replace(',','.'),quantity=Number(quantityText),unitPriceMinor=parseArgentineMinor(row.querySelector('.line-unit').value);return {description:row.querySelector('.line-description').value.trim(),quantityMilli:Number.isFinite(quantity)?Math.round(quantity*1000):null,unitPriceMinor}})}
function updateInvoiceCalculation(){const currency=document.getElementById('invoiceCurrency')?.value||'ARS',items=invoiceFormItems(),subtotal=items.reduce((sum,item)=>sum+(Number.isSafeInteger(item.quantityMilli)&&Number.isSafeInteger(item.unitPriceMinor)?Math.round(item.quantityMilli*item.unitPriceMinor/1000):0),0);[...document.querySelectorAll('#invoiceItems .invoice-item')].forEach((row,index)=>{const item=items[index],line=Number.isSafeInteger(item?.quantityMilli)&&Number.isSafeInteger(item?.unitPriceMinor)?Math.round(item.quantityMilli*item.unitPriceMinor/1000):0;row.querySelector('.line-subtotal').textContent=formatMoneyMinor(line,currency)});const discount=parseArgentineMinor(document.getElementById('invoiceDiscount')?.value)||0,tax=parseArgentineMinor(document.getElementById('invoiceTax')?.value)||0,total=subtotal-discount+tax;document.getElementById('invoiceSubtotal').textContent=formatMoneyMinor(subtotal,currency);document.getElementById('invoiceTotal').textContent=formatMoneyMinor(Math.max(0,total),currency)}
function resetInvoiceForm(){editingInvoiceId=null;document.getElementById('createSaasInvoice').textContent='Confirmar y emitir factura';document.getElementById('invoiceNumber').disabled=false;document.getElementById('invoiceNumber').value='';document.getElementById('invoiceItems').innerHTML='';addInvoiceLine();document.getElementById('invoiceDiscount').value='0,00';document.getElementById('invoiceTax').value='0,00';updateInvoiceCalculation()}
async function loadSubscriptionInvoiceDraft(){const clientId=document.getElementById('invoiceClient')?.value,message=document.getElementById('invoiceMessage');if(!clientId){message.textContent='Seleccioná un consultorio.';return}message.textContent='Preparando el borrador desde la suscripción vigente…';try{const response=await fetch(saasEndpoint(`/api/saas/clients/${encodeURIComponent(clientId)}/subscription`)),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo cargar la suscripción.');const draft=data.invoiceDraft;editingInvoiceId=null;document.getElementById('invoiceItems').innerHTML='';draft.items.forEach(item=>addInvoiceLine({description:item.description,quantity:Number(item.quantityMilli)/1000,unitPrice:(Number(item.unitPriceMinor)/100).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})}));document.getElementById('invoiceCurrency').value=draft.currency;document.getElementById('invoiceDiscount').value='0,00';document.getElementById('invoiceTax').value='0,00';updateInvoiceCalculation();message.textContent=`Borrador cargado: ${formatMoneyMinor(draft.totalMinor,draft.currency)}${draft.arsEquivalentMinor?` · equivalente ${formatMoneyMinor(draft.arsEquivalentMinor,'ARS')}`:''}. No se cobró ni se emitió ninguna factura fiscal.`}catch(error){message.textContent=error.message}}
function editSaasInvoice(id){const invoice=saasInvoices.find(item=>item.id===id);if(!invoice||Number(invoice.paid_minor||0)>0)return alert('Las facturas con pagos confirmados están protegidas y no pueden editarse.');editingInvoiceId=id;document.getElementById('invoiceClient').value=invoice.client_id;document.getElementById('invoiceNumber').value=invoice.invoice_number||invoice.id;document.getElementById('invoiceNumber').disabled=true;document.getElementById('invoiceCurrency').value=invoice.currency;document.getElementById('invoiceIssuedAt').value=String(invoice.issued_at||'').slice(0,10);document.getElementById('invoiceDueAt').value=String(invoice.due_at||'').slice(0,10);document.getElementById('invoiceDiscount').value=(Number(invoice.discount_minor||0)/100).toLocaleString('es-AR',{minimumFractionDigits:2});document.getElementById('invoiceTax').value=(Number(invoice.tax_minor||0)/100).toLocaleString('es-AR',{minimumFractionDigits:2});const body=document.getElementById('invoiceItems');body.innerHTML='';(invoice.items||[]).forEach(item=>addInvoiceLine({description:item.description,quantity:Number(item.quantity_milli||1000)/1000,unitPrice:(Number(item.unit_price_minor||0)/100).toLocaleString('es-AR',{minimumFractionDigits:2})}));if(!body.children.length)addInvoiceLine();document.getElementById('createSaasInvoice').textContent='Guardar cambios de la factura';document.getElementById('invoiceMessage').textContent=`Editando ${invoice.invoice_number||invoice.id}. Los pagos confirmados bloquean cambios.`;document.querySelector('#saas-billing .billing-form-card')?.scrollIntoView({behavior:'smooth',block:'start'});updateInvoiceCalculation()}
function selectedPaymentInvoice(){return saasInvoices.find(item=>item.id===document.getElementById('paymentInvoice')?.value)}
function syncPaymentInvoice(){const invoice=selectedPaymentInvoice();if(invoice){document.getElementById('paymentClient').value=invoice.client_id;document.getElementById('paymentCurrency').value=invoice.currency}updatePaymentCalculation()}
function updatePaymentCalculation(){const invoice=selectedPaymentInvoice(),paymentCurrency=document.getElementById('paymentCurrency')?.value||'ARS',paymentStatus=document.getElementById('paymentStatus')?.value||'confirmed',amount=parseArgentineMinor(document.getElementById('paymentAmount')?.value)||0,show=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};show('paymentCurrentAmount',formatMoneyMinor(amount,paymentCurrency));if(!invoice){show('paymentInvoiceTotal','Sin factura asociada');show('paymentPriorPaid','—');show('paymentAccumulated','—');show('paymentRemaining','—');return}const same=paymentCurrency===invoice.currency,applied=paymentStatus==='confirmed'?(same?amount:null):0;show('paymentInvoiceTotal',formatMoneyMinor(invoice.amount_minor,invoice.currency));show('paymentPriorPaid',formatMoneyMinor(invoice.paid_minor,invoice.currency));if(applied===null){show('paymentAccumulated','Se calculará con la cotización vigente');show('paymentRemaining',formatMoneyMinor(invoice.balance_minor,invoice.currency)+' antes de convertir')}else{show('paymentAccumulated',formatMoneyMinor(Number(invoice.paid_minor||0)+applied,invoice.currency));show('paymentRemaining',formatMoneyMinor(Math.max(0,Number(invoice.balance_minor||0)-applied),invoice.currency))}}
const paymentEffectiveLabel=payment=>({confirmed:'Confirmado',pending:'Pendiente',rejected:'Rechazado',corrected:'Corregido',reversal:'Reversión',voided:'Anulado'}[payment.effective_status||payment.status]||paymentStatusLabel(payment.status||'confirmed'));
function paymentActionButton(payment){const locked=Boolean(payment.reverses_payment_id||payment.superseded_by_payment_id||payment.correction_state==='voided');return `<div class="payment-row-actions"><button class="secondary viewPaymentCorrection" data-payment="${safeUser(payment.id)}" type="button">Ver / Corregir</button>${locked?'':`<button class="danger-action deletePaymentFromHistory" data-payment="${safeUser(payment.id)}" type="button">${(payment.status||'confirmed')==='confirmed'?'Anular':'Eliminar'}</button>`}</div>`}
function invoicePaymentHistory(invoice){const payments=invoice.payments||[];if(!payments.length)return '<p class="detail">Esta factura todavía no tiene pagos registrados.</p>';return `<table class="payment-history-mini"><thead><tr><th>Fecha</th><th>Importe</th><th>Método</th><th>Estado</th><th>Registrado por</th><th>Acción</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${formatBillingDate(p.paid_at)}</td><td>${formatMoneyMinor(p.amount_minor??Math.round(Number(p.amount||0)*100),p.currency)}</td><td>${safeUser(p.method||'—')}</td><td>${safeUser(paymentEffectiveLabel(p))}</td><td>${safeUser(p.registered_by_name||'Sistema')}</td><td>${paymentActionButton(p)}</td></tr>`).join('')}</tbody></table>`}
function closePaymentCorrection(){const dialog=document.getElementById('paymentCorrectionDialog');dialog?.close();dialog?.classList.remove('is-fullscreen');const expand=document.getElementById('expandPaymentCorrection');if(expand)expand.textContent='⛶ Pantalla completa';selectedCorrectionPaymentId=null}
function openPaymentCorrection(id,focusDelete=false){const payment=saasPayments.find(item=>item.id===id),dialog=document.getElementById('paymentCorrectionDialog');if(!payment||!dialog)return;selectedCorrectionPaymentId=id;dialog.classList.remove('is-fullscreen');document.getElementById('paymentCorrectionIdentity').textContent=`${payment.id} · ${paymentEffectiveLabel(payment)} · registrado por ${payment.registered_by_name||'Sistema'}`;const clientSelect=document.getElementById('correctionClient'),invoiceSelect=document.getElementById('correctionInvoice'),invoice=saasInvoices.find(item=>item.id===payment.invoice_id);clientSelect.innerHTML=document.getElementById('paymentClient').innerHTML;clientSelect.value=payment.client_id;invoiceSelect.innerHTML='<option value="">Sin factura asociada</option>'+saasInvoices.map(i=>`<option value="${safeUser(i.id)}">${safeUser(i.invoice_number||i.id)} · ${safeUser(i.client_name)}</option>`).join('');invoiceSelect.value=payment.invoice_id||'';document.getElementById('correctionInvoiceNumber').textContent=invoice?.invoice_number||payment.invoice_number||'Sin factura asociada';document.getElementById('correctionInvoiceClient').textContent=invoice?.client_name||payment.client_name||'—';document.getElementById('correctionInvoiceDate').textContent=invoice?formatBillingDate(invoice.issued_at):'—';document.getElementById('correctionInvoiceTotal').textContent=invoice?formatMoneyMinor(invoice.amount_minor,invoice.currency):'—';document.getElementById('correctionInvoicePaid').textContent=invoice?formatMoneyMinor(invoice.paid_minor,invoice.currency):'—';document.getElementById('correctionInvoiceBalance').textContent=invoice?formatMoneyMinor(invoice.balance_minor,invoice.currency):'—';document.getElementById('correctionAmount').value=(Number(payment.amount_minor??Math.round(Number(payment.amount||0)*100))/100).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});document.getElementById('correctionCurrency').value=payment.currency||'ARS';document.getElementById('correctionDate').value=String(payment.paid_at||'').slice(0,10);document.getElementById('correctionMethod').value=payment.method||'';document.getElementById('correctionReference').value=payment.reference||'';document.getElementById('correctionStatus').value=payment.status||'confirmed';document.getElementById('correctionNotes').value=payment.notes||'';document.getElementById('correctionReason').value='';document.getElementById('paymentCorrectionMessage').textContent='';const confirmed=(payment.status||'confirmed')==='confirmed',editable=!payment.reverses_payment_id&&!payment.superseded_by_payment_id&&payment.correction_state!=='voided',directButton=document.getElementById('savePaymentDirect'),correctionButton=document.getElementById('savePaymentCorrection'),deleteButton=document.getElementById('deletePayment');document.getElementById('correctionStatus').disabled=confirmed;document.getElementById('paymentCorrectionPolicy').textContent=confirmed?'Pago confirmado: cualquier corrección o anulación conservará el original mediante asientos auditados. La sesión Superadmin actual es suficiente.':'Pago no confirmado: puede editarse o eliminarse directamente. La operación quedará registrada en auditoría.';directButton.hidden=!editable||confirmed;correctionButton.hidden=!editable||!confirmed;deleteButton.hidden=!editable;deleteButton.textContent=confirmed?'Anular pago':'Eliminar pago';document.getElementById('paymentCorrectionHistory').innerHTML=(payment.corrections||[]).length?`<h3 class="section-title">Historial de modificaciones</h3>`+payment.corrections.map(item=>`<div class="payment-correction-event"><b>${formatBillingDate(item.created_at)} · ${safeUser(item.corrected_by_name||'Sistema')}</b><div>${safeUser(item.reason)}</div><small>${safeUser({direct_edit:'Edición directa auditada',reversal_and_replacement:'Reversión y nuevo registro',direct_delete:'Eliminación de borrador',audited_void:'Anulación auditada'}[item.correction_type]||item.correction_type)}</small></div>`).join(''):'<p class="detail">Este pago no tiene correcciones anteriores.</p>';dialog.showModal();if(focusDelete)setTimeout(()=>document.getElementById('correctionReason')?.focus(),0)}
function updateCorrectionInvoiceSummary(){const invoice=saasInvoices.find(item=>item.id===document.getElementById('correctionInvoice')?.value),payment=saasPayments.find(item=>item.id===selectedCorrectionPaymentId);if(invoice)document.getElementById('correctionClient').value=invoice.client_id;document.getElementById('correctionInvoiceNumber').textContent=invoice?.invoice_number||payment?.invoice_number||'Sin factura asociada';document.getElementById('correctionInvoiceClient').textContent=invoice?.client_name||payment?.client_name||'—';document.getElementById('correctionInvoiceDate').textContent=invoice?formatBillingDate(invoice.issued_at):'—';document.getElementById('correctionInvoiceTotal').textContent=invoice?formatMoneyMinor(invoice.amount_minor,invoice.currency):'—';document.getElementById('correctionInvoicePaid').textContent=invoice?formatMoneyMinor(invoice.paid_minor,invoice.currency):'—';document.getElementById('correctionInvoiceBalance').textContent=invoice?formatMoneyMinor(invoice.balance_minor,invoice.currency):'—'}
async function savePaymentCorrection(){const payment=saasPayments.find(item=>item.id===selectedCorrectionPaymentId);if(!payment)return;const amountMinor=parseArgentineMinor(document.getElementById('correctionAmount').value),reason=document.getElementById('correctionReason').value.trim(),confirmed=(payment.status||'confirmed')==='confirmed',payload={clientId:document.getElementById('correctionClient').value,invoiceId:document.getElementById('correctionInvoice').value,amountMinor,currency:document.getElementById('correctionCurrency').value,paidAt:document.getElementById('correctionDate').value,method:document.getElementById('correctionMethod').value,reference:document.getElementById('correctionReference').value,status:document.getElementById('correctionStatus').value,notes:document.getElementById('correctionNotes').value,reason,idempotencyKey:crypto.randomUUID()},message=document.getElementById('paymentCorrectionMessage'),button=document.getElementById(confirmed?'savePaymentCorrection':'savePaymentDirect');if(!amountMinor||!payload.method||!reason){message.textContent='Completá importe, método y motivo de la corrección.';return}if(!confirm(confirmed?'Se conservará el pago original y se generarán una reversión y un nuevo pago. ¿Continuar?':'Se guardará la edición con historial auditable. ¿Continuar?'))return;button.disabled=true;message.textContent='Validando y recalculando factura…';try{const endpoint=confirmed?`/api/saas/payments/${encodeURIComponent(payment.id)}/corrections`:`/api/saas/payments/${encodeURIComponent(payment.id)}`,response=await fetch(saasEndpoint(endpoint),{method:confirmed?'POST':'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo corregir el pago.');closePaymentCorrection();await Promise.all([loadSaasBilling(),loadSaasDashboard(),loadAuditCenter(),loadPartnership()])}catch(error){message.textContent=error.message}finally{button.disabled=false}}
function togglePaymentCorrectionFullscreen(){const dialog=document.getElementById('paymentCorrectionDialog'),button=document.getElementById('expandPaymentCorrection');if(!dialog)return;const expanded=dialog.classList.toggle('is-fullscreen');if(button)button.textContent=expanded?'↙ Salir de pantalla completa':'⛶ Pantalla completa'}
