async function deleteSelectedPayment(){const payment=saasPayments.find(item=>item.id===selectedCorrectionPaymentId),reason=document.getElementById('correctionReason').value.trim(),message=document.getElementById('paymentCorrectionMessage'),button=document.getElementById('deletePayment');if(!payment)return;if(!reason){message.textContent='Ingresá el motivo de la eliminación o anulación.';document.getElementById('correctionReason').focus();return}const confirmed=(payment.status||'confirmed')==='confirmed';if(!confirm(confirmed?'El pago confirmado quedará anulado mediante una reversión auditable. ¿Continuar?':'El pago no confirmado se eliminará de la lista. ¿Continuar?'))return;button.disabled=true;message.textContent=confirmed?'Generando anulación auditada…':'Eliminando registro…';try{const response=await fetch(saasEndpoint(`/api/saas/payments/${encodeURIComponent(payment.id)}`),{method:'DELETE',headers:{'content-type':'text/plain'},body:JSON.stringify({reason})}),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo completar la operación.');closePaymentCorrection();await Promise.all([loadSaasBilling(),loadSaasDashboard(),loadAuditCenter(),loadPartnership()])}catch(error){message.textContent=error.message}finally{button.disabled=false}}
async function loadSaasBilling(){try{const response=await fetch(saasEndpoint('/api/saas/billing')),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo cargar facturación.');saasInvoices=data.invoices||[];saasPayments=data.payments||[];const counts=data.summary?.counts||{},ars=data.summary?.totals?.ARS||{},usd=data.summary?.totals?.USD||{};document.getElementById('billingPaidCount').textContent=counts.paid||0;document.getElementById('billingPartialCount').textContent=counts.partial||0;document.getElementById('billingPendingCount').textContent=(counts.pending||0)+(counts.past_due||0);document.getElementById('billingOutstanding').innerHTML=`<span class="billing-currency-block">${formatMoneyMinor(ars.pendingMinor||0,'ARS')}</span><span class="billing-currency-block">${formatMoneyMinor(usd.pendingMinor||0,'USD')}</span>`;document.getElementById('saasInvoiceHistory').innerHTML=saasInvoices.length?saasInvoices.map(i=>`<tr><td><b>${safeUser(i.invoice_number||i.id)}</b><br><small>${Number(i.items?.length||0)} concepto(s)</small></td><td>${safeUser(i.client_name)}</td><td>${formatBillingDate(i.issued_at)}<br><small>Vence ${formatBillingDate(i.due_at)}</small></td><td>${formatMoneyMinor(i.subtotal_minor,i.currency)}</td><td>-${formatMoneyMinor(i.discount_minor,i.currency)}<br><small>+${formatMoneyMinor(i.tax_minor,i.currency)}</small></td><td class="billing-history-total">${formatMoneyMinor(i.amount_minor,i.currency)}</td><td>${formatMoneyMinor(i.paid_minor,i.currency)}</td><td class="billing-history-total">${formatMoneyMinor(i.balance_minor,i.currency)}</td><td><span class="billing-status ${safeUser(i.status)}">${safeUser(invoiceStatusLabel(i.status))}</span></td><td>${Number(i.paid_minor||0)===0?`<button class="secondary editInvoice" data-invoice="${safeUser(i.id)}" type="button">Editar</button>`:'<span class="detail">Protegida</span>'}</td></tr><tr class="invoice-payment-row"><td colspan="10"><details><summary>Historial de pagos (${Number(i.payments?.length||0)})</summary>${invoicePaymentHistory(i)}</details></td></tr>`).join(''):'<tr><td colspan="10" class="detail">Todavía no hay facturas emitidas.</td></tr>';document.getElementById('saasPaymentHistory').innerHTML=saasPayments.length?saasPayments.map(p=>`<tr><td>${formatBillingDate(p.paid_at)}</td><td><b>${safeUser(p.client_name)}</b><br><small>${safeUser(p.invoice_number||'Sin factura')}</small></td><td>${formatMoneyMinor(p.amount_minor??Math.round(Number(p.amount||0)*100),p.currency)}</td><td>${p.invoice_id?formatMoneyMinor(p.applied_amount_minor??p.amount_minor,p.applied_currency||p.currency):'Sin aplicar'}</td><td>${safeUser(p.method||'—')}<br><small>${safeUser(p.reference||'Sin referencia')}</small></td><td><span class="billing-status ${safeUser(p.effective_status||p.status||'confirmed')}">${safeUser(paymentEffectiveLabel(p))}</span></td><td>${safeUser(p.registered_by_name||'Sistema')}</td><td><div class="billing-payment-note">${safeUser(p.notes||'—')}</div></td><td>${paymentActionButton(p)}</td></tr>`).join(''):'<tr><td colspan="9" class="detail">Todavía no hay pagos registrados.</td></tr>';document.querySelectorAll('.editInvoice').forEach(button=>button.onclick=()=>editSaasInvoice(button.dataset.invoice));document.querySelectorAll('.viewPaymentCorrection').forEach(button=>button.onclick=()=>openPaymentCorrection(button.dataset.payment));document.querySelectorAll('.deletePaymentFromHistory').forEach(button=>button.onclick=()=>openPaymentDeletion(button.dataset.payment));const select=document.getElementById('paymentInvoice');if(select){const selected=select.value;select.innerHTML='<option value="">Sin factura asociada</option>'+saasInvoices.filter(i=>i.status!=='paid').map(i=>`<option value="${safeUser(i.id)}">${safeUser(i.invoice_number||i.id)} · ${safeUser(i.client_name)} · saldo ${formatMoneyMinor(i.balance_minor,i.currency)}</option>`).join('');if([...select.options].some(x=>x.value===selected))select.value=selected}updatePaymentCalculation()}catch(error){console.warn(error.message)}}
async function createSaasInvoice(){const message=document.getElementById('invoiceMessage'),button=document.getElementById('createSaasInvoice'),items=invoiceFormItems(),discountMinor=parseArgentineMinor(document.getElementById('invoiceDiscount').value),taxMinor=parseArgentineMinor(document.getElementById('invoiceTax').value),payload={clientId:document.getElementById('invoiceClient').value,invoiceNumber:document.getElementById('invoiceNumber').value,currency:document.getElementById('invoiceCurrency').value,issuedAt:document.getElementById('invoiceIssuedAt').value,dueAt:document.getElementById('invoiceDueAt').value,discountMinor,taxMinor,items};if(!items.length||items.some(item=>!item.description||!Number.isSafeInteger(item.quantityMilli)||item.quantityMilli<=0||!Number.isSafeInteger(item.unitPriceMinor))||discountMinor===null||taxMinor===null){message.textContent='Revisá conceptos, cantidades e importes. Usá por ejemplo 1.500,50.';return}const editing=Boolean(editingInvoiceId);if(!confirm(`${editing?'Se guardarán los cambios':'Se emitirá la factura'} por ${document.getElementById('invoiceTotal').textContent}. ¿Confirmás?`))return;button.disabled=true;message.textContent=editing?'Actualizando factura…':'Guardando factura…';try{const endpoint=editing?`/api/saas/invoices/${encodeURIComponent(editingInvoiceId)}`:'/api/saas/invoices',response=await fetch(saasEndpoint(endpoint),{method:editing?'PATCH':'POST',headers:{'content-type':'text/plain'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo guardar.');message.textContent=editing?'Factura actualizada y auditada.':`Factura ${data.invoiceNumber} emitida y persistida. Total ${formatMoneyMinor(data.amountMinor,data.currency)}.`;resetInvoiceForm();await Promise.all([loadSaasBilling(),loadSaasDashboard(),loadAuditCenter()])}catch(error){message.textContent=error.message}finally{button.disabled=false}}
async function createSaasPayment(){const message=document.getElementById('paymentMessage'),button=document.getElementById('createSaasPayment'),amountMinor=parseArgentineMinor(document.getElementById('paymentAmount').value),payload={clientId:document.getElementById('paymentClient').value,invoiceId:document.getElementById('paymentInvoice').value,amountMinor,currency:document.getElementById('paymentCurrency').value,status:document.getElementById('paymentStatus').value,paidAt:document.getElementById('paymentDate').value,method:document.getElementById('paymentMethod').value,reference:document.getElementById('paymentReference').value,notes:document.getElementById('paymentNotes').value,idempotencyKey:crypto.randomUUID()};if(!amountMinor||!payload.method){message.textContent='Ingresá un importe válido y seleccioná el medio de pago.';return}if(!confirm(`Se registrará un pago ${paymentStatusLabel(payload.status).toLowerCase()} por ${formatMoneyMinor(amountMinor,payload.currency)}. ¿Confirmás?`))return;button.disabled=true;message.textContent='Registrando y verificando el pago…';try{const response=await fetch(saasEndpoint('/api/saas/payments'),{method:'POST',headers:{'content-type':'text/plain'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo registrar.');message.textContent=`Pago ${data.id} guardado. ${data.balanceMinor===null?'Sin factura asociada.':`Saldo restante: ${formatMoneyMinor(data.balanceMinor,data.appliedCurrency)}.`}`;document.getElementById('paymentAmount').value='';document.getElementById('paymentReference').value='';document.getElementById('paymentNotes').value='';await Promise.all([loadSaasBilling(),loadSaasDashboard(),loadSaasClients(),loadAuditCenter(),loadPartnership()])}catch(error){message.textContent=error.message}finally{button.disabled=false}}
function parseSignedMinor(value){const text=String(value||'').trim(),negative=text.startsWith('-'),minor=parseArgentineMinor(negative?text.slice(1):text);return minor===null?null:(negative?-minor:minor)}
function partnershipMoneyList(map,field){return Object.entries(map||{}).map(([currency,value])=>`${formatMoneyMinor(value?.[field]||0,currency)}`).join(' · ')||'—'}
async function loadPartnership(){const section=document.getElementById('saas-partnership');if(!section)return;const period=document.getElementById('partnershipPeriod')?.value||new Date().toISOString().slice(0,7),expenseRate=Math.round(Number(document.getElementById('partnershipExpenseRate')?.value||20)*100),message=document.getElementById('partnershipMessage');try{const response=await fetch(saasEndpoint(`/api/saas/partnership?period=${encodeURIComponent(period)}&expenseRateBps=${expenseRate}`)),data=await response.json();if(response.status===403){document.getElementById('partnershipNav')?.setAttribute('hidden','');section.setAttribute('hidden','');return}if(!response.ok)throw new Error(data.error||'No se pudo cargar la sociedad.');partnershipState=data;document.getElementById('partnershipNav')?.removeAttribute('hidden');section.removeAttribute('hidden');document.getElementById('partnerActiveClients').textContent=data.metrics.activeClients;document.getElementById('partnerPaidClients').textContent=data.metrics.paidClients;document.getElementById('partnerMoroseClients').textContent=data.metrics.moroseClients;message.textContent=`Período ${data.period.period} · Datos reales actualizados desde cobros, gastos, ajustes y retiros confirmados.`;document.getElementById('partnershipCurrencyCards').innerHTML=Object.values(data.metrics.currencies).map(item=>`<article class="card currency-profit-card ${item.netResultMinor<0?'loss':''}"><div class="toolbar"><h2 class="section-title">Resultado ${safeUser(item.currency)}</h2><span class="tag">Cobros reales</span></div><div class="formula-row"><span>Ingresos cobrados</span><b>${formatMoneyMinor(item.collectedMinor,item.currency)}</b></div><div class="formula-row"><span>Gastos, impuestos y reservas</span><b>- ${formatMoneyMinor(item.expensesMinor,item.currency)}</b></div><div class="formula-row"><span>Ajustes auditables</span><b>${formatMoneyMinor(item.adjustmentsMinor,item.currency)}</b></div><div class="formula-row"><span>Ganancia neta</span><b>${formatMoneyMinor(item.netResultMinor,item.currency)}</b></div><div class="formula-row"><span>${item.netResultMinor<0?'Pérdida registrada':'Ganancia distribuible'}</span><b>${formatMoneyMinor(item.netResultMinor<0?item.lossMinor:item.distributableMinor,item.currency)}</b></div><div class="partner-money"><span>Ezequiel 50%<b>${formatMoneyMinor(item.shares.ezequiel,item.currency)}</b></span><span>Matías 50%<b>${formatMoneyMinor(item.shares.matias,item.currency)}</b></span><span>Retiros del período<b>${formatMoneyMinor(data.metrics.periodWithdrawals[item.currency]||0,item.currency)}</b></span></div></article>`).join('');document.getElementById('partnershipPartnerCards').innerHTML=data.partners.map(partner=>`<article class="card partner-card"><h2>${safeUser(partner.display_name)}</h2><p class="detail">Socio · 50% fijo · ${partner.username?`Cuenta @${safeUser(partner.username)}`:'Cuenta pendiente de vincular'}</p><div class="partner-money"><span>Derecho acumulado<b>${partnershipMoneyList(data.balances[partner.id],'entitlementMinor')}</b></span><span>Retiros realizados<b>${partnershipMoneyList(data.balances[partner.id],'withdrawnMinor')}</b></span><span>Saldo pendiente<b>${partnershipMoneyList(data.balances[partner.id],'availableMinor')}</b></span></div></article>`).join('');document.getElementById('partnershipProjectionBody').innerHTML=data.projections.scenarios.map(row=>`<tr><td><b>${row.clients}</b></td><td>${row.composition.basic} / ${row.composition.medium} / ${row.composition.premium}</td><td>${formatMoneyMinor(row.revenueUsdMinor,'USD')}</td><td>${formatMoneyMinor(row.estimatedExpensesUsdMinor,'USD')}</td><td>${formatMoneyMinor(row.resultUsdMinor,'USD')}</td><td>${formatMoneyMinor(row.ezequielUsdMinor,'USD')}</td><td>${formatMoneyMinor(row.matiasUsdMinor,'USD')}</td></tr>`).join('');const history=[...data.expenses.map(row=>({date:row.occurred_at,type:'Gasto',detail:`${row.concept} · ${row.category}`,amount:-Number(row.amount_minor),currency:row.currency,actor:row.created_by})),...data.adjustments.map(row=>({date:row.occurred_at,type:'Ajuste',detail:row.concept,amount:Number(row.amount_minor),currency:row.currency,actor:row.created_by})),...data.withdrawals.map(row=>({date:row.withdrawal_date,type:`Retiro ${row.partner_name}`,detail:`${row.method}${row.extraordinary?' · extraordinario':''}`,amount:-Number(row.amount_minor),currency:row.currency,actor:row.authorized_by}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)));document.getElementById('partnershipHistoryBody').innerHTML=history.length?history.map(row=>`<tr><td>${formatBillingDate(row.date)}</td><td>${safeUser(row.type)}</td><td>${safeUser(row.detail)}</td><td>${formatMoneyMinor(row.amount,row.currency)}</td><td>${safeUser(row.currency)}</td><td>${safeUser(row.actor||'—')}</td></tr>`).join(''):'<tr><td colspan="6">No hay movimientos para este período.</td></tr>';document.getElementById('distributionHistory').innerHTML=data.distributions.length?data.distributions.map(row=>`<div class="agenda-row"><div><b>${safeUser(row.period_start.slice(0,7))} · ${safeUser(row.currency)}</b><small>Distribuible ${formatMoneyMinor(row.distributable_minor,row.currency)} · Ezequiel ${formatMoneyMinor(row.ezequiel_share_minor,row.currency)} · Matías ${formatMoneyMinor(row.matias_share_minor,row.currency)}</small></div><span class="tag ${row.status==='approved'?'':'wait'}">${row.status==='approved'?'Aprobada por ambos':`${row.approval_count}/2 aprobaciones`}</span></div>`).join(''):'Todavía no hay cierres guardados.';renderPartnerAccountLinks()}catch(error){message.textContent=error.message}}
function renderPartnerAccountLinks(){if(!partnershipState)return;const target=document.getElementById('partnerAccountLinks'),options=partnershipState.superadmins.map(user=>`<option value="${safeUser(user.id)}">${safeUser(user.display_name)} · @${safeUser(user.username)}</option>`).join('');target.innerHTML=partnershipState.partners.map(partner=>`<div class="partner-link-row" data-partner="${partner.id}"><div><b>${safeUser(partner.display_name)} · 50%</b><small class="detail">${partner.username?`Vinculado a @${safeUser(partner.username)}`:'Pendiente de vincular'}</small></div><label>Cuenta Superadmin<select class="partnerAccountSelect"><option value="">Seleccionar…</option>${options}</select></label><button class="secondary savePartnerLink">Vincular</button></div>`).join('');partnershipState.partners.forEach(partner=>{const row=target.querySelector(`[data-partner="${partner.id}"]`);if(partner.professional_user_id)row.querySelector('select').value=partner.professional_user_id;row.querySelector('button').onclick=()=>savePartnerLink(row)})}
async function savePartnerLink(row){const response=await fetch(saasEndpoint('/api/saas/partnership/partners'),{method:'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify({partnerId:row.dataset.partner,userId:row.querySelector('select').value})}),data=await response.json();if(!response.ok)return alert(data.error||'No se pudo vincular.');await loadPartnership()}
async function partnershipPost(path,payload,success){const message=document.getElementById('partnershipMessage'),response=await fetch(saasEndpoint(path),{method:'POST',headers:{'content-type':'text/plain'},body:JSON.stringify({...payload,idempotencyKey:payload.idempotencyKey||crypto.randomUUID()})}),data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error||'No se pudo guardar.'),{data});message.textContent=success;await Promise.all([loadPartnership(),loadAuditCenter()]);return data}
async function savePartnerExpense(){const amountMinor=parseArgentineMinor(document.getElementById('partnerExpenseAmount').value);if(!amountMinor)return alert('Ingresá un importe válido.');if(!confirm('El gasto quedará confirmado y no podrá eliminarse. ¿Continuar?'))return;try{await partnershipPost('/api/saas/partnership/expenses',{concept:document.getElementById('partnerExpenseConcept').value,category:document.getElementById('partnerExpenseCategory').value,amountMinor,currency:document.getElementById('partnerExpenseCurrency').value,occurredAt:document.getElementById('partnerExpenseDate').value,notes:document.getElementById('partnerExpenseNotes').value},'Gasto confirmado y distribución recalculada.');document.getElementById('partnerExpenseAmount').value='';document.getElementById('partnerExpenseConcept').value=''}catch(error){alert(error.message)}}
async function savePartnerAdjustment(){const amountMinor=parseSignedMinor(document.getElementById('partnerAdjustmentAmount').value);if(!amountMinor)return alert('Ingresá un ajuste válido, positivo o negativo.');if(!confirm('El ajuste quedará registrado como corrección auditable. ¿Continuar?'))return;try{await partnershipPost('/api/saas/partnership/adjustments',{concept:document.getElementById('partnerAdjustmentConcept').value,amountMinor,currency:document.getElementById('partnerAdjustmentCurrency').value,occurredAt:document.getElementById('partnerAdjustmentDate').value,notes:document.getElementById('partnerAdjustmentNotes').value},'Ajuste confirmado y distribución recalculada.');document.getElementById('partnerAdjustmentAmount').value='';document.getElementById('partnerAdjustmentConcept').value=''}catch(error){alert(error.message)}}
async function savePartnerWithdrawal(){const amountMinor=parseArgentineMinor(document.getElementById('partnerWithdrawalAmount').value),extraordinary=document.getElementById('partnerWithdrawalExtraordinary').checked,payload={partnerId:document.getElementById('partnerWithdrawalPartner').value,amountMinor,currency:document.getElementById('partnerWithdrawalCurrency').value,method:document.getElementById('partnerWithdrawalMethod').value,withdrawalDate:document.getElementById('partnerWithdrawalDate').value,notes:document.getElementById('partnerWithdrawalNotes').value,extraordinary};if(!amountMinor)return alert('Ingresá un importe válido.');if(extraordinary){payload.extraordinaryReason=prompt('Motivo obligatorio del retiro extraordinario:')||'';payload.confirmation=prompt('Escribí exactamente: AUTORIZAR RETIRO EXTRAORDINARIO')||'';payload.reauthPassword=prompt('Ingresá tu contraseña de Superadmin:')||''}if(!confirm(`Se registrará un retiro de ${formatMoneyMinor(amountMinor,payload.currency)} para ${payload.partnerId==='ezequiel'?'Ezequiel':'Matías'}. ¿Confirmás?`))return;try{await partnershipPost('/api/saas/partnership/withdrawals',payload,'Retiro persistido y saldo actualizado.');document.getElementById('partnerWithdrawalAmount').value=''}catch(error){if(error.data?.availableMinor!==undefined)alert(`${error.message}\nDisponible: ${formatMoneyMinor(error.data.availableMinor,payload.currency)}`);else alert(error.message)}}
async function approvePartnershipDistribution(currency){const period=document.getElementById('partnershipPeriod').value;if(!confirm(`Aprobar el cierre ${currency} de ${period} con tu cuenta de socio. Se volverá inmutable cuando ambos socios aprueben. ¿Continuar?`))return;try{const data=await partnershipPost('/api/saas/partnership/distributions/approve',{period,currency},'Aprobación registrada.');alert(data.status==='approved'?'Cierre aprobado por ambos socios.':`Aprobación ${data.approvals}/2 registrada. Falta el otro socio.`)}catch(error){alert(error.message)}}
async function exportPartnershipReport(){const period=document.getElementById('partnershipPeriod').value,response=await fetch(saasEndpoint(`/api/saas/partnership/export?period=${encodeURIComponent(period)}`));if(!response.ok){const data=await response.json();return alert(data.error||'No se pudo exportar.')}const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`nexora-sociedad-${period}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
async function loadSaasPlans(){try{const response=await fetch(saasEndpoint("/api/saas/plans")),rows=await response.json();if(!response.ok)throw new Error(rows.error||"No se pudieron cargar los planes.");saasPlans=rows;const moduleOptions=SYSTEM_FUNCTIONS.filter(([key])=>!COMMERCIAL_FUNCTIONS.includes(key)&&key!=="plans"),labels={basic:"Esencial",medium:"Más elegido",premium:"Más completo"},target=document.getElementById("saasPlanEditor");if(!target)return;target.innerHTML=rows.map(p=>`<article class="plan-card card" data-plan-card="${p.plan}" data-saas-plan="${p.plan}"><span class="plan-badge">${labels[p.plan]||safeUser(p.name)}</span><h2>Plan ${safeUser(p.name)}</h2><div class="plan-price">${formatPlanPrice(p.offer_active&&p.offer_price?p.offer_price:p.monthly_price,p.currency)}</div><p class="detail"><b>${Number(saasDashboardData.subscriptions?.[p.plan]||0)} clientes</b> actualmente en este plan.</p><label class="detail">Precio mensual<input class="saasPlanPrice" type="number" min="0" value="${Number(p.monthly_price||0)}"></label><label class="detail">Moneda<input class="saasPlanCurrency" value="${safeUser(p.currency)}"></label><label class="detail">Límite de pacientes<input class="saasPlanLimit" type="number" min="1" ${p.plan==='premium'?'disabled':''} value="${p.patient_limit===null?'':Number(p.patient_limit)}" placeholder="${p.plan==='premium'?'Ilimitados':'Cantidad máxima'}"></label><label class="detail plan-offer-toggle"><input class="saasPlanOfferActive" type="checkbox" ${p.offer_active?'checked':''}> Oferta activa</label><label class="detail">Nombre de la oferta<input class="saasPlanOfferLabel" value="${safeUser(p.offer_label||'') }" placeholder="Ej. Lanzamiento"></label><label class="detail">Precio promocional<input class="saasPlanOfferPrice" type="number" min="0" value="${Number(p.offer_price||0)}"></label><label class="detail">Características, una por línea<textarea class="saasPlanFeatures">${safeUser((p.features||[]).join('\n'))}</textarea></label><div class="detail"><b>Módulos habilitados</b><div class="saasPlanModules">${moduleOptions.map(([key,label])=>`<label style="display:block;margin-top:6px"><input type="checkbox" value="${key}" ${(p.modules||[]).includes(key)?'checked':''}> ${label}</label>`).join('')}</div></div></article>`).join("");}catch(error){console.warn(error.message);}}
async function saveSaasPlans(){const plans=[...document.querySelectorAll('[data-saas-plan]')].map(card=>({plan:card.dataset.saasPlan,monthlyPrice:card.querySelector('.saasPlanPrice').value,currency:card.querySelector('.saasPlanCurrency').value,patientLimit:card.querySelector('.saasPlanLimit').disabled?null:card.querySelector('.saasPlanLimit').value,offerActive:card.querySelector('.saasPlanOfferActive').checked,offerLabel:card.querySelector('.saasPlanOfferLabel').value,offerPrice:card.querySelector('.saasPlanOfferPrice').value,features:card.querySelector('.saasPlanFeatures').value.split('\n').map(x=>x.trim()).filter(Boolean),modules:[...card.querySelectorAll('.saasPlanModules input:checked')].map(input=>input.value)})),message=document.getElementById("saasPlanMessage");message.textContent="Guardando…";const response=await fetch(saasEndpoint("/api/saas/plans"),{method:"PATCH",headers:{"content-type":"text/plain"},body:JSON.stringify({plans})}),data=await response.json();message.textContent=response.ok?"Planes, precios y ofertas actualizados.":data.error||"No se pudieron guardar.";if(response.ok)await Promise.all([loadSaasPlans(),loadSaasDashboard()]);}
async function loadFeatureMatrix(){const target=document.getElementById('featureMatrix');if(!target)return;try{const response=await fetch(saasEndpoint('/api/saas/features')),rows=await response.json();if(!response.ok)throw new Error(rows.error||'No se pudo cargar el catálogo.');saasFeatures=rows;const planLabel={basic:'Básico',medium:'Intermedio',premium:'Premium'},typeLabel={boolean:'Sí / no',count:'Cantidad',monthly:'Mensual',storage_mb:'MB'};target.innerHTML=`<div class="feature-row header"><div>Funcionalidad</div><div>Básico</div><div>Intermedio</div><div>Premium</div><div>Tipo de límite</div><div>Configuración</div><div>Estado</div></div>`+rows.map(f=>`<div class="feature-row" data-feature-key="${safeUser(f.feature_key)}" data-limit-type="${safeUser(f.limit_type||'boolean')}"><div><b>${safeUser(f.name)}</b><small>${safeUser(f.category)} · ${safeUser(f.description)}</small></div>${['basic','medium','premium'].map(plan=>`<div class="feature-plan-cell"><input aria-label="${planLabel[plan]} habilitado" type="checkbox" data-plan="${plan}" ${f[`${plan}_enabled`]?'checked':''}>${f.limit_type&&f.limit_type!=='boolean'?`<input aria-label="Límite ${planLabel[plan]}" type="number" min="0" data-limit-plan="${plan}" value="${f[`${plan}_limit`]??''}" placeholder="Sin límite">`:'<span class="detail">Incluida</span>'}</div>`).join('')}<div>${safeUser(typeLabel[f.limit_type]||f.limit_type||'Sí / no')}</div><div class="detail">Base central<br>+ excepción por clínica</div><div><span class="feature-status">${safeUser(f.status||'active')}</span></div></div>`).join('');await loadFeatureHistory();}catch(error){target.innerHTML=`<p class="detail">${safeUser(error.message)}</p>`}}
async function saveFeatureMatrix(){const message=document.getElementById('featureMatrixMessage'),features=[...document.querySelectorAll('#featureMatrix [data-feature-key]')].map(row=>({key:row.dataset.featureKey,...Object.fromEntries(['basic','medium','premium'].flatMap(plan=>[[plan,row.querySelector(`[data-plan="${plan}"]`).checked],[`${plan}Limit`,row.querySelector(`[data-limit-plan="${plan}"]`)?.value??null]]))}));if(!confirm('Este cambio modificará las prestaciones efectivas de todas las clínicas vinculadas a estos planes. ¿Querés continuar?'))return;const reason=prompt('Motivo del cambio masivo:','Actualización comercial de planes');if(reason===null)return;message.textContent='Guardando…';const response=await fetch(saasEndpoint('/api/saas/features'),{method:'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify({features,reason})}),data=await response.json();message.textContent=response.ok?'Matriz actualizada y registrada en el historial.':data.error||'No se pudo guardar.';if(response.ok)await Promise.all([loadFeatureMatrix(),loadAdminAudit(),loadMonitoring()]);}
