async function loadMonitoring(){const table=document.getElementById('monitorTable');if(!table&&!document.getElementById('saasWhatsappList'))return;const search=document.getElementById('monitorSearch')?.value||'',plan=document.getElementById('monitorPlan')?.value||'',status=document.getElementById('monitorStatus')?.value||'';try{const response=await fetch(saasEndpoint(`/api/saas/monitoring?search=${encodeURIComponent(search)}&plan=${encodeURIComponent(plan)}&status=${encodeURIComponent(status)}`)),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo cargar el monitoreo.');const set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};set('monitorActive',data.summary.activeClients);set('monitorRecent',data.summary.recentClients);set('monitorUsers',data.summary.activeUsers);set('monitorExpiring',data.summary.expiringSoon);set('monitorAutomations',data.summary.activeAutomations);set('monitorErrors',data.summary.integrationErrors);set('monitorUsage',data.summary.externalUsage);if(table)table.innerHTML=data.items.length?data.items.map(item=>`<tr><td><b>${safeUser(item.name)}</b><br><small>${safeUser(item.subscription_status)}</small></td><td>${item.plan==='medium'?'Intermedio':safeUser(item.plan)}</td><td>${item.last_access?new Date(item.last_access).toLocaleString('es-AR'):'Nunca'}</td><td>${Number(item.active_users||0)}</td><td><span class="${item.whatsapp_status==='connected'?'monitor-ok':'monitor-warn'}">${safeUser(item.whatsapp_status||'desconectado')}</span></td><td>${Number(item.active_automations||0)}</td><td>${Number(item.integration_errors||0)}</td></tr>`).join(''):'<tr><td colspan="7">Sin resultados.</td></tr>';const wa=document.getElementById('saasWhatsappList');if(wa)wa.innerHTML=data.items.map(item=>`<div class="agenda-row"><div><b>${safeUser(item.name)}</b><small>Plan ${item.plan==='medium'?'Intermedio':safeUser(item.plan)} · Última sincronización ${item.whatsapp_last_sync?new Date(item.whatsapp_last_sync).toLocaleString('es-AR'):'sin sincronización'}</small></div><span class="tag ${item.whatsapp_status==='connected'?'':'wait'}">${safeUser(item.whatsapp_status||'disconnected')}</span></div>`).join('')||'No hay clínicas.';}catch(error){if(table)table.innerHTML=`<tr><td colspan="7">${safeUser(error.message)}</td></tr>`}}
