async function createSupportIncident(){const message=document.getElementById('supportMessage'),payload={clientId:document.getElementById('supportClient').value,title:document.getElementById('supportTitle').value,priority:document.getElementById('supportPriority').value,description:document.getElementById('supportDescription').value},response=await fetch(saasEndpoint('/api/saas/support-incidents'),{method:'POST',headers:{'content-type':'text/plain'},body:JSON.stringify(payload)}),data=await response.json();message.textContent=response.ok?`Incidencia ${data.id} registrada.`:data.error||'No se pudo registrar.';if(response.ok){document.getElementById('supportTitle').value='';document.getElementById('supportDescription').value='';await Promise.all([loadSupportIncidents(),loadAdminAudit()]);}}
