let fxState={current:null,settings:null,history:[]},usdMigrationPreview=null;
const moneyArs=value=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',minimumFractionDigits:2}).format(Number(value||0));
const moneyUsd=value=>`US$ ${Number(value||0).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
async function loadExchangeRates(){if(!document.getElementById('fxRate'))return;try{const response=await fetch(saasEndpoint('/api/saas/exchange-rates')),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo consultar la cotización.');fxState=data;const q=data.current||{},settings=data.settings||{},set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};set('fxRate',q.sell?`$ ${Number(q.sell).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})}`:'No disponible');set('fxSource',q.source||'Sin cotización');set('fxUpdated',q.fetchedAt?new Date(q.fetchedAt).toLocaleString('es-AR'):'—');set('fxOriginLabel',String(settings.origin||q.origin||'oficial').toUpperCase());set('fxIntervalLabel',`${Math.round(Number(settings.interval_seconds||300)/60)} min`);set('fxStatus',q.unavailable?'SIN DATOS':q.stale?'ÚLTIMO VALOR VÁLIDO':q.isManual?'MANUAL':'CONECTADO');document.getElementById('fxOrigin').value=settings.origin||'oficial';document.getElementById('fxInterval').value=String(settings.interval_seconds||300);document.getElementById('fxHistory').innerHTML=(data.history||[]).map(item=>`<tr><td>${new Date(item.fetchedAt).toLocaleString('es-AR')}</td><td>${safeUser(String(item.origin).toUpperCase())}</td><td>${moneyArs(item.sell)}</td><td>${safeUser(item.source)}</td><td><span class="tag ${item.isManual?'wait':''}">${item.isManual?'Manual':'Automática'}</span></td><td>${safeUser(item.actorName||'Sistema')}</td></tr>`).join('')||'<tr><td colspan="6">Todavía no hay cotizaciones registradas.</td></tr>';updatePlanArsPreviews();}catch(error){document.getElementById('fxStatus').textContent='ERROR';document.getElementById('fxMessage').textContent=error.message;}}
async function saveFxSettings(){const message=document.getElementById('fxMessage'),response=await fetch(saasEndpoint('/api/saas/exchange-rates/settings'),{method:'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify({origin:document.getElementById('fxOrigin').value,intervalSeconds:document.getElementById('fxInterval').value})}),data=await response.json();message.textContent=response.ok?'Configuración guardada.':data.error||'No se pudo guardar.';if(response.ok)await refreshExchangeRate();}
async function refreshExchangeRate(){const message=document.getElementById('fxMessage');message.textContent='Consultando MonedAPI…';const response=await fetch(saasEndpoint('/api/saas/exchange-rates/refresh'),{method:'POST',headers:{'content-type':'text/plain'},body:'{}'}),data=await response.json();message.textContent=response.ok?'Cotización actualizada.':data.error||data.quote?.error||'No se pudo actualizar.';await loadExchangeRates();}
async function saveManualExchangeRate(){const sell=document.getElementById('manualFxSell').value,reason=document.getElementById('manualFxReason').value;if(!sell||!reason.trim())return alert('Ingresá la cotización y el motivo obligatorio.');if(!confirm(`Se aplicará una cotización manual de venta ${sell}. ¿Confirmás?`))return;const response=await fetch(saasEndpoint('/api/saas/exchange-rates/manual'),{method:'POST',headers:{'content-type':'text/plain'},body:JSON.stringify({sell,reason})}),data=await response.json();if(!response.ok)return alert(data.error||'No se pudo guardar.');document.getElementById('manualFxSell').value='';document.getElementById('manualFxReason').value='';await loadExchangeRates();}
async function previewUsdMigration(){const target=document.getElementById('usdMigrationPreview');target.innerHTML='Preparando conversión con la cotización vigente…';const response=await fetch(saasEndpoint('/api/saas/plan-price-migration/preview'),{method:'POST',headers:{'content-type':'text/plain'},body:'{}'}),data=await response.json();if(!response.ok){target.textContent=data.error||'No se pudo preparar.';return}usdMigrationPreview=data;target.innerHTML=`<div class="plan-note"><b>Cotización usada:</b> ${moneyArs(data.quote.sell)} · ${safeUser(data.quote.source)} · ${new Date(data.quote.fetchedAt).toLocaleString('es-AR')}</div><div style="overflow:auto"><table class="billing-table"><thead><tr><th>Plan</th><th>Precio original</th><th>Nuevo precio base</th><th>Equivalente de control</th></tr></thead><tbody>${data.plans.map(p=>`<tr><td><b>${safeUser(p.name)}</b></td><td>${moneyArs(p.originalArs)}</td><td>${moneyUsd(p.usd)}</td><td>${moneyArs(p.arsEquivalentMinor/100)}</td></tr>`).join('')}</tbody></table></div><div class="commercial-form" style="margin-top:16px"><label>Para aplicar, escribí exactamente: <b>${data.confirmationText}</b><input id="usdMigrationConfirmation" autocomplete="off"></label></div><button class="primary" id="applyUsdMigration" type="button">Aplicar migración definitiva</button><p class="detail">No se modificarán contratos vigentes, facturas ni pagos históricos.</p>`;document.getElementById('applyUsdMigration').onclick=applyUsdMigration;}
async function applyUsdMigration(){if(!usdMigrationPreview)return;const confirmation=document.getElementById('usdMigrationConfirmation').value;if(confirmation!==usdMigrationPreview.confirmationText)return alert('La frase de confirmación no coincide.');if(!confirm('Esta acción fijará los precios base de los planes en USD. ¿Aplicar definitivamente?'))return;const response=await fetch(saasEndpoint('/api/saas/plan-price-migration/apply'),{method:'POST',headers:{'content-type':'text/plain'},body:JSON.stringify({previewId:usdMigrationPreview.id,confirmation})}),data=await response.json();if(!response.ok)return alert(data.error||'No se pudo aplicar.');alert('Migración aplicada y auditada.');usdMigrationPreview=null;await Promise.all([loadExchangeRates(),loadSaasPlans(),loadAdminAudit()]);}
function updatePlanArsPreviews(){const sell=Number(fxState.current?.sell||0);document.querySelectorAll('[data-saas-plan]').forEach(card=>{const usd=Number(card.querySelector('.saasPlanUsd')?.value||0),target=card.querySelector('.saasPlanArsPreview');if(target)target.textContent=usd&&sell?`Equivalente aproximado: ${moneyArs(usd*sell)}`:'Conversión ARS pendiente';});}
function enhanceSaasPlanCurrencyEditor(){document.querySelectorAll('[data-saas-plan]').forEach(card=>{if(card.querySelector('.usd-price-editor'))return;const plan=saasPlans.find(p=>p.plan===card.dataset.saasPlan);card.querySelector('.saasPlanCurrency')?.setAttribute('readonly','');card.querySelector('.saasPlanPrice')?.closest('label')?.insertAdjacentHTML('afterend',`<div class="usd-price-editor"><label class="detail">Precio mensual USD<input class="saasPlanUsd" inputmode="decimal" value="${plan?.monthly_price_usd_cents===null||plan?.monthly_price_usd_cents===undefined?'':(Number(plan.monthly_price_usd_cents)/100).toFixed(2)}" placeholder="Pendiente de migración"></label><label class="detail">Precio anual USD<input class="saasPlanAnnualUsd" inputmode="decimal" value="${plan?.annual_price_usd_cents===null||plan?.annual_price_usd_cents===undefined?'':(Number(plan.annual_price_usd_cents)/100).toFixed(2)}"></label><label class="detail plan-offer-toggle"><input class="saasPlanActive" type="checkbox" ${plan?.price_active===0?'':'checked'}> Plan activo</label><div class="plan-note saasPlanArsPreview">Conversión ARS pendiente</div></div>`);card.querySelector('.saasPlanUsd').addEventListener('input',updatePlanArsPreviews)});updatePlanArsPreviews();}
async function saveSaasPlansUsd(){const plans=[...document.querySelectorAll('[data-saas-plan]')].map(card=>({plan:card.dataset.saasPlan,monthlyPrice:card.querySelector('.saasPlanPrice').value,patientLimit:card.dataset.saasPlan==='premium'?null:card.querySelector('.saasPlanLimit').value,monthlyUsd:card.querySelector('.saasPlanUsd')?.value??null,annualUsd:card.querySelector('.saasPlanAnnualUsd')?.value??null,active:card.querySelector('.saasPlanActive')?.checked!==false,currency:card.querySelector('.saasPlanCurrency').value,offerActive:card.querySelector('.saasPlanOfferActive').checked,offerLabel:card.querySelector('.saasPlanOfferLabel').value,offerPrice:card.querySelector('.saasPlanOfferPrice').value,features:card.querySelector('.saasPlanFeatures').value.split('\n').map(x=>x.trim()).filter(Boolean),modules:[...card.querySelectorAll('.saasPlanModules input:checked')].map(input=>input.value)})),message=document.getElementById('saasPlanMessage');message.textContent='Guardando…';const response=await fetch(saasEndpoint('/api/saas/plans'),{method:'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify({plans})}),data=await response.json();message.textContent=response.ok?'Planes, precios y límites actualizados con auditoría.':data.error||'No se pudieron guardar.';if(response.ok){await loadSaasPlans();enhanceSaasPlanCurrencyEditor();await Promise.all([loadSaasDashboard(),loadAdminAudit()])}}

async function loadPracticePlan() {
  const token = connectionToken(); if (!token) return;
  try {
    const response = await fetch(`${TRIAGE_API}/api/practice-plan?token=${encodeURIComponent(token)}${supportSuffix()}`), data = await response.json();
    if (!response.ok) throw new Error(data.error || "No se pudo consultar el plan.");
    practicePlan = data; renderPracticePlan(data);
    const user = JSON.parse(sessionStorage.getItem("odontocentroProfessional") || "{}"); applyPermissions(user); loadCommunicationSuite();
  } catch (error) {
    console.warn(error.message);
    document.querySelector('.nav button[data-view="plans"]')?.removeAttribute('hidden');
    document.getElementById("currentPlanName").textContent = "Mi plan y suscripción";
    document.getElementById("currentPlanDescription").textContent = "No pudimos actualizar los datos del plan en este momento. Podés consultar igualmente la comparación y volver a intentar sin perder información.";
    const notice=document.getElementById('planChangeNotice');if(notice){notice.hidden=false;notice.textContent=`No se pudo actualizar la suscripción: ${error.message}`;notice.classList.add('error')}
  }
}
function renderPracticePlan(data) {
  const names = {basic:"Plan Básico",medium:"Plan Intermedio",premium:"Plan Premium"}, descriptions = {basic:"Operación esencial para hasta 50 pacientes, con historia clínica básica, agenda, tratamientos y cobros.",medium:"Gestión ampliada para hasta 500 pacientes, más profesionales, reportes, exportación y WhatsApp manual.",premium:"Clínica integral con pacientes ilimitados, automatizaciones, múltiples sucursales, auditoría y análisis avanzado."};
  const statusLabels = {active:"Activa",past_due:"Vencida",pending:"Pendiente de pago",suspended:"Suspendida"};
  document.getElementById("currentPlanName").textContent = names[data.plan] || "Plan contratado";
  const currentUser = JSON.parse(sessionStorage.getItem("odontocentroProfessional") || "{}");
  document.getElementById("currentPlanDescription").textContent = currentUser.role === "superadmin" ? `${descriptions[data.plan] || ""} Tu cuenta Super Admin mantiene acceso total equivalente a Premium.` : descriptions[data.plan] || "";
  const status = document.getElementById("subscriptionStatus"); status.textContent = statusLabels[data.status] || "Activa"; status.className = `subscription-status ${data.status === "active" ? "" : data.status === "suspended" ? "stop" : "warn"}`;
  document.getElementById("subscriptionStart").textContent = `Inicio: ${formatBillingDate(data.startedAt)}`;
  document.getElementById("subscriptionRenewal").textContent = `Próxima renovación: ${formatBillingDate(data.renewsAt)}`;
  document.getElementById("currentContractedPrice").textContent = data.administratorOverride ? "Premium permanente incluido · sin facturación" : `Precio contratado: ${formatPlanPrice(data.contractedPrice,data.currency)}`;
  document.getElementById("currentPlanFeatures").textContent = data.features?.length ? `Funciones incluidas: ${data.features.join(" · ")}` : "Funciones habilitadas según tu plan.";
  const changeNotice=document.getElementById('planChangeNotice');if(changeNotice){changeNotice.classList.remove('error');changeNotice.hidden=!data.requestedPlan;changeNotice.textContent=data.requestedPlan?`Cambio solicitado: Plan ${data.requestedPlan==='medium'?'Intermedio':data.requestedPlan==='premium'?'Premium':'Básico'}. La solicitud está pendiente de aprobación.`:''}
  document.getElementById("patientUsage").textContent = `${data.patientCount} pacientes`;
  document.getElementById("patientLimit").textContent = data.unlimited ? "Ilimitados" : `de ${data.limit}`;
  const percentage = data.unlimited ? Math.min(100, data.patientCount ? 18 : 0) : Math.min(100, Math.round((data.patientCount / data.limit) * 100));
  document.getElementById("patientUsageBar").style.width = `${percentage}%`;
  document.getElementById("patientRemaining").textContent = data.unlimited ? "Sin límite de crecimiento" : `${data.remaining} lugares disponibles`;
  const warning = document.getElementById("patientLimitWarning"),level=data.atLimit?"100":percentage>=90?"90":percentage>=80?"80":""; warning.dataset.level=level;warning.style.display = level ? "block" : "none"; warning.textContent = data.atLimit ? "Capacidad completa (100%). Las nuevas altas quedan bloqueadas; las solicitudes de Triage se preservan pendientes para no perderlas." : percentage >= 90 ? `Capacidad crítica: ${percentage}% utilizado. Solicitá una ampliación o mejorá el plan.` : `Aviso preventivo: ya utilizaste el ${percentage}% del límite de pacientes.`;
  document.querySelectorAll("[data-private-price]").forEach(el => { const plan=(data.availablePlans||[]).find(item=>item.plan===el.dataset.privatePrice);el.textContent = formatPlanPrice(plan?.effectivePrice??data.prices?.[el.dataset.privatePrice], plan?.currency||data.currency); });
  (data.availablePlans||[]).forEach(plan=>{const card=document.querySelector(`#plans [data-plan-card="${plan.plan}"]`);if(!card)return;const price=card.querySelector('[data-private-price]'),detail=card.querySelector('.detail'),list=card.querySelector('ul'),badge=card.querySelector('.plan-badge');if(price&&plan.offerActive){price.innerHTML=`<small style="display:block;text-decoration:line-through;font-size:13px">${formatPlanPrice(plan.monthlyPrice,plan.currency)}</small>${formatPlanPrice(plan.effectivePrice,plan.currency)}`;}if(detail)detail.innerHTML=`<b>${plan.patientLimit===null?'Pacientes ilimitados':`Hasta ${plan.patientLimit} pacientes`}.</b> ${plan.plan==='basic'?'Inicio digital simple y profesional.':plan.plan==='medium'?'Gestión diaria centralizada.':'Control clínico y administrativo completo.'}`;if(list&&plan.features?.length)list.innerHTML=plan.features.map(feature=>`<li>${safeUser(feature)}</li>`).join('');if(badge&&plan.offerActive&&plan.offerLabel)badge.textContent=plan.offerLabel;});
  document.getElementById("billingHistory").innerHTML = data.invoices?.length ? data.invoices.map(invoice => `<tr><td>${formatBillingDate(invoice.issued_at)}</td><td>${safeUser(invoice.concept)}</td><td>${formatMoney(invoice.amount,invoice.currency)}</td><td><span class="tag ${invoice.status === "paid" ? "" : "wait"}">${{paid:"Pagada",pending:"Pendiente",failed:"Rechazada",cancelled:"Cancelada"}[invoice.status] || safeUser(invoice.status)}</span></td><td>${invoice.receipt_url ? `<a href="${safeUser(invoice.receipt_url)}" target="_blank" rel="noopener">Ver</a>` : "—"}</td></tr>`).join("") : '<tr><td colspan="5" class="detail">Todavía no hay comprobantes registrados.</td></tr>';
  document.querySelectorAll("[data-plan-card]").forEach(card => card.classList.toggle("current", card.dataset.planCard === data.plan));
  document.querySelectorAll(".request-upgrade").forEach(button => {
    const target = button.dataset.plan, current = target === data.plan;
    button.disabled = current || data.requestedPlan === target;
    button.textContent = current ? "Plan actual seleccionado" : data.requestedPlan === target ? "Solicitud pendiente" : `Elegir ${target === "medium" ? "Intermedio" : target === "premium" ? "Premium" : "Básico"}`;
    button.onclick = () => openPrivatePlanCart(target);
  });
  document.getElementById("priceBasic").value = data.prices?.basic || ""; document.getElementById("priceMedium").value = data.prices?.medium || ""; document.getElementById("pricePremium").value = data.prices?.premium || ""; document.getElementById("billingCurrency").value = data.currency || "ARS"; document.getElementById("billingWhatsapp").value = data.whatsapp || ""; document.getElementById("billingPaymentUrl").value = data.paymentUrl || ""; document.getElementById("manualPlan").value = data.plan; document.getElementById("manualStatus").value = data.status || "active"; document.getElementById("manualStartedAt").value = data.startedAt || ""; document.getElementById("manualRenewsAt").value = data.renewsAt || "";
  renderFeatureAccess();
}
function featureEnabled(key) {
  try { if (JSON.parse(sessionStorage.getItem("odontocentroProfessional") || "{}").role === "superadmin") return true; } catch (_) {}
  return practicePlan.effectiveFeatures?.[key] === true;
}
function renderFeatureAccess() {
  const details = Object.fromEntries((practicePlan.featureDetails || []).map(item => [item.feature_key, item]));
  document.querySelectorAll("[data-feature]").forEach(card => {
    const key = card.dataset.feature, enabled = featureEnabled(key), detail = details[key];
    card.classList.toggle("feature-locked", !enabled);
    card.querySelectorAll("button,input,select,textarea").forEach(control => { control.disabled = !enabled; });
    card.querySelector(".feature-lock-note")?.remove();
    if (!enabled) card.insertAdjacentHTML("beforeend", `<div class="feature-lock-note"><b>🔒 Función no incluida</b><span>${safeUser(detail?.description || "Esta función no está habilitada para tu suscripción.")} El Superadmin puede habilitarla o podés solicitar un cambio de plan.</span><button class="secondary request-feature-upgrade" type="button">Ver planes disponibles</button></div>`);
  });
  document.querySelectorAll(".request-feature-upgrade").forEach(button => button.onclick = () => document.getElementById("plans")?.scrollIntoView({behavior:"smooth",block:"start"}));
}
function formatBillingDate(value) { if (!value) return "—"; const date = new Date(`${String(value).slice(0,10)}T12:00:00`); return Number.isNaN(date.getTime()) ? "—" : date.toLocaleDateString("es-AR"); }
function formatMoney(value,currency="ARS") { const code=currency==='USD'?'USD':'ARS',prefix=code==='USD'?'US$':'$';return `${prefix} ${new Intl.NumberFormat("es-AR",{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value)||0)}`; }
function formatPlanPrice(value,currency="ARS") { if (value === "" || value == null) return "Precio a consultar"; const number=Number(value); return Number.isFinite(number)&&number>0 ? `${formatMoney(number,currency)} / mes` : `${safeUser(value)} / mes`; }
async function requestPlanUpgrade(plan) {
  const response = await fetch(`${TRIAGE_API}/api/practice-plan/upgrade-request?token=${encodeURIComponent(connectionToken())}`, {method:"POST",headers:{"content-type":"text/plain"},body:JSON.stringify({plan})}), data = await response.json();
  if (!response.ok) return alert(data.error || "No se pudo registrar la solicitud.");
  alert("Solicitud pendiente de aprobación. Nos pondremos en contacto para coordinar el cambio sin perder información."); loadPracticePlan();
}
function openPrivatePlanCart(plan) {
  document.getElementById("privatePlanCart")?.remove();const names={basic:"Básico",medium:"Intermedio",premium:"Premium"},selected=(practicePlan.availablePlans||[]).find(item=>item.plan===plan),limit=selected?.patientLimit===null?"Pacientes ilimitados":`Hasta ${selected?.patientLimit||0} pacientes`,overlay=document.createElement("div");overlay.id="privatePlanCart";overlay.className="plan-cart-overlay";overlay.innerHTML=`<div class="plan-cart-dialog ${plan}"><button class="plan-cart-close" type="button" aria-label="Cerrar">×</button><span class="cart-kicker">Carrito · Cambio de plan</span><h2>Plan ${names[plan]}</h2><p class="detail">${limit}</p><div class="cart-summary"><div><b>Suscripción mensual</b><small>Cambio desde ${practicePlan.planName || "tu plan actual"}</small></div><strong>${formatPlanPrice(selected?.effectivePrice??practicePlan.prices?.[plan],selected?.currency||practicePlan.currency)}</strong></div><p class="cart-guarantee">Toda la información clínica y administrativa se conserva. Sin pasarela configurada, la solicitud queda pendiente de aprobación y no se informa un pago exitoso.</p><div class="billing-actions"><button class="primary" id="confirmPlanCart" type="button">Solicitar cambio de plan</button><button class="secondary" id="cancelPlanCart" type="button">Cancelar</button></div><p class="cart-message" id="privateCartMessage"></p></div>`;document.body.append(overlay);document.getElementById("cancelPlanCart").onclick=()=>overlay.remove();overlay.onclick=event=>{if(event.target===overlay)overlay.remove()};document.getElementById("confirmPlanCart").onclick=()=>submitPrivatePlanCart(plan);
}
function focusPlanComparison(){const grid=document.getElementById('planComparisonGrid');if(!grid)return;grid.scrollIntoView({behavior:'smooth',block:'start'});grid.classList.remove('plan-focus');requestAnimationFrame(()=>grid.classList.add('plan-focus'));setTimeout(()=>grid.classList.remove('plan-focus'),1800)}
async function submitPrivatePlanCart(plan) {
  const message=document.getElementById("privateCartMessage");message.textContent="Registrando la solicitud…";try{const response=await fetch(`${TRIAGE_API}/api/subscription-orders`,{method:"POST",headers:{"content-type":"text/plain"},body:JSON.stringify({plan,token:connectionToken(),source:"private_panel"})}),order=await response.json();if(!response.ok)throw new Error(order.error||"No se pudo preparar el carrito.");message.textContent=`Solicitud ${order.id} pendiente de aprobación.`;if(order.paymentUrl)window.open(order.paymentUrl,"_blank","noopener");else{const phone=String(order.whatsapp||"").replace(/\D/g,""),text=`Hola, quiero solicitar el cambio al Plan ${order.planName}. Pedido ${order.id}. Importe mensual: ${formatPlanPrice(order.price,order.currency)}.`;if(phone)window.open(`https://wa.me/${phone}?text=${encodeURIComponent(text)}`,"_blank","noopener");}loadPracticePlan();}catch(error){message.textContent=error.message;}
}
function openPayment() { if (practicePlan.paymentUrl) return window.open(practicePlan.paymentUrl,"_blank","noopener"); const phone=String(practicePlan.whatsapp||"").replace(/\D/g,""); if (phone) return window.open(`https://wa.me/${phone}?text=${encodeURIComponent(`Hola, quiero pagar mi ${practicePlan.planName || "plan"} del sistema odontológico.`)}`,"_blank","noopener"); alert("Configurá un enlace de pago o WhatsApp desde la configuración comercial."); }
async function saveCommercialConfig() { const message=document.getElementById("commercialMessage"), payload={prices:{basic:document.getElementById("priceBasic").value,medium:document.getElementById("priceMedium").value,premium:document.getElementById("pricePremium").value},currency:document.getElementById("billingCurrency").value,whatsapp:document.getElementById("billingWhatsapp").value,paymentUrl:document.getElementById("billingPaymentUrl").value}; const response=await fetch(`${TRIAGE_API}/api/subscription-config?token=${encodeURIComponent(connectionToken())}`,{method:"PATCH",headers:{"content-type":"text/plain"},body:JSON.stringify(payload)}),data=await response.json(); message.textContent=response.ok?"Configuración comercial guardada.":data.error||"No se pudo guardar."; if(response.ok)loadPracticePlan(); }
async function saveManualPlan() { const message=document.getElementById("commercialMessage"), payload={plan:document.getElementById("manualPlan").value,status:document.getElementById("manualStatus").value,startedAt:document.getElementById("manualStartedAt").value,renewsAt:document.getElementById("manualRenewsAt").value}; const response=await fetch(`${TRIAGE_API}/api/practice-plan?token=${encodeURIComponent(connectionToken())}`,{method:"PATCH",headers:{"content-type":"text/plain"},body:JSON.stringify(payload)}),data=await response.json(); message.textContent=response.ok?"Plan y estado actualizados sin modificar los datos clínicos.":data.error||"No se pudo actualizar."; if(response.ok)loadPracticePlan(); }

let selectedConversationId = null;
async function loadCommunicationSuite() {
  renderCommunicationAccess();
  const tasks=[loadNotifications()];
  if(featureEnabled("whatsapp_business")) tasks.push(loadWhatsappSettings(),loadConversations());
  if(featureEnabled("role_notifications")) tasks.push(loadNotificationPreferences());
  if(featureEnabled("automations")) tasks.push(loadAutomations());
  await Promise.all(tasks);
}
function hasPremiumAccess(){return featureEnabled("whatsapp_business")}
function renderCommunicationAccess() {
  const gate=document.getElementById("communicationsGate"),app=document.getElementById("communicationsApp"),enabled=featureEnabled("whatsapp_business"),detail=(practicePlan.featureDetails||[]).find(item=>item.feature_key==="whatsapp_business");
  if(gate)gate.innerHTML=enabled?"":`<div class="plan-lock"><h2>Centro de comunicaciones no habilitado</h2><p>${safeUser(detail?.description||"La bandeja integrada de WhatsApp Business no está incluida en tu configuración actual.")}</p><button class="primary" onclick="document.getElementById('plans')?.scrollIntoView({behavior:'smooth'})">Ver opciones de plan</button></div>`;
  if(app)app.style.display=enabled?"grid":"none";
}
async function loadWhatsappSettings() {
    try{const response=await fetch(`${TRIAGE_API}/api/whatsapp/settings?token=${encodeURIComponent(connectionToken())}`),data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo cargar WhatsApp.");const labels={connected:"Conectado",disconnected:"Desconectado",pending:"Pendiente",error:"Error"},dot=document.getElementById("waConnectionDot");document.getElementById("waConnectionStatus").textContent=labels[data.status]||data.status;dot.className=`connection-dot ${data.status}`;document.getElementById("waConnectionDetails").textContent=data.officialApi?"Cloud API oficial de Meta":"Sin integración oficial";document.getElementById("waAccountName").textContent=data.accountName||"—";document.getElementById("waPhoneNumber").textContent=data.phoneNumber||"—";document.getElementById("waLastSync").textContent=data.lastSyncAt?new Date(data.lastSyncAt).toLocaleString("es-AR"):"—";document.getElementById("connectWhatsapp").disabled=data.status==="connected";document.getElementById("disconnectWhatsapp").disabled=data.status==="disconnected";document.getElementById("waNotifyUsers").innerHTML=(data.users||[]).map(user=>`<label style="display:block;margin:7px 0"><input type="checkbox" value="${user.id}" ${data.notifyUserIds.includes(user.id)?"checked":""}> ${safeUser(user.display_name)} · ${safeUser(user.role)}</label>`).join("")||"No hay usuarios activos.";}catch(error){document.getElementById("waConnectionMessage").textContent=error.message;}
}
async function saveWhatsappRecipients(){const ids=[...document.querySelectorAll('#waNotifyUsers input:checked')].map(input=>input.value),response=await fetch(`${TRIAGE_API}/api/whatsapp/settings?token=${encodeURIComponent(connectionToken())}`,{method:"PATCH",headers:{"content-type":"text/plain"},body:JSON.stringify({notifyUserIds:ids})}),data=await response.json();if(!response.ok)return alert(data.error||"No se pudo guardar.");loadWhatsappSettings();}
const NOTIFICATION_TYPES={web_appointment:"Nuevo turno desde la web",whatsapp_message:"Nuevo mensaje de WhatsApp",unanswered:"Conversación sin responder",appointment_confirmed:"Turno confirmado",appointment_cancelled:"Turno cancelado",appointment_rescheduled:"Turno reprogramado",debt_limit:"Paciente cerca del límite de deuda",plan_expiring:"Plan próximo a vencer",payment_pending:"Pago pendiente",patient_limit:"Límite de pacientes"};
async function loadNotificationPreferences(){const target=document.getElementById("notificationRolePrefs");if(!target)return;try{const response=await fetch(`${TRIAGE_API}/api/notification-preferences?token=${encodeURIComponent(connectionToken())}`),rows=await response.json(),saved=Object.fromEntries((rows||[]).map(row=>[row.notification_type,JSON.parse(row.roles_json||'[]')]));target.innerHTML=Object.entries(NOTIFICATION_TYPES).map(([key,label])=>`<div class="automation-card" data-pref="${key}"><b>${label}</b><div>${['admin','odontologo','secretaria','asistente'].map(role=>`<label style="display:inline-block;margin:8px 12px 0 0"><input type="checkbox" value="${role}" ${(saved[key]||['admin']).includes(role)?'checked':''}> ${role}</label>`).join('')}</div><button class="secondary savePref" type="button">Guardar</button></div>`).join('');target.querySelectorAll('.savePref').forEach(button=>button.onclick=()=>saveNotificationPreference(button.closest('[data-pref]')));}catch(error){target.textContent=error.message;}}
async function saveNotificationPreference(row){const roles=[...row.querySelectorAll('input:checked')].map(input=>input.value),response=await fetch(`${TRIAGE_API}/api/notification-preferences?token=${encodeURIComponent(connectionToken())}`,{method:"PATCH",headers:{"content-type":"text/plain"},body:JSON.stringify({type:row.dataset.pref,roles})}),data=await response.json();if(!response.ok)return alert(data.error||'No se pudo guardar.');}
async function changeWhatsappConnection(action) { const message=document.getElementById("waConnectionMessage"),response=await fetch(`${TRIAGE_API}/api/whatsapp/${action}?token=${encodeURIComponent(connectionToken())}`,{method:"POST",headers:{"content-type":"text/plain"},body:"{}"}),data=await response.json();message.textContent=data.message||data.error||(response.ok?"Estado actualizado.":"No se pudo actualizar.");if(response.ok)loadWhatsappSettings(); }
async function loadAutomations() { const target=document.getElementById("automationList");try{const response=await fetch(`${TRIAGE_API}/api/whatsapp/automations?token=${encodeURIComponent(connectionToken())}`),items=await response.json();if(!response.ok)throw new Error(items.error||"No se pudieron cargar.");target.innerHTML=items.map(item=>`<article class="automation-card" data-automation="${item.id}"><div style="display:flex;justify-content:space-between;gap:12px"><b>${safeUser(item.name)}</b><label class="tag"><input type="checkbox" class="automationActive" ${item.active?"checked":""}> Activa</label></div><label class="detail">Cuándo se envía<input class="automationTiming" value="${safeUser(item.timing)}"></label><textarea class="automationText">${safeUser(item.template_text)}</textarea><div class="detail">Vista previa: <span class="automationPreview">${safeUser(item.template_text)}</span></div><button class="primary saveAutomation" type="button">Guardar automatización</button></article>`).join("");target.querySelectorAll(".saveAutomation").forEach(button=>button.onclick=()=>saveAutomation(button.closest("[data-automation]")));target.querySelectorAll(".automationText").forEach(input=>input.oninput=()=>input.closest("article").querySelector(".automationPreview").textContent=input.value);}catch(error){target.innerHTML=`<p class="detail">${safeUser(error.message)}</p>`;} }
async function saveAutomation(card) { const response=await fetch(`${TRIAGE_API}/api/whatsapp/automations/${encodeURIComponent(card.dataset.automation)}?token=${encodeURIComponent(connectionToken())}`,{method:"PATCH",headers:{"content-type":"text/plain"},body:JSON.stringify({active:card.querySelector(".automationActive").checked,timing:card.querySelector(".automationTiming").value,templateText:card.querySelector(".automationText").value})}),data=await response.json();if(!response.ok)return alert(data.error||"No se pudo guardar.");loadAutomations(); }
async function loadConversations() { const target=document.getElementById("conversationList"),search=document.getElementById("commSearch")?.value||"",filter=document.getElementById("commFilter")?.value||"all";try{const response=await fetch(`${TRIAGE_API}/api/whatsapp/conversations?token=${encodeURIComponent(connectionToken())}&search=${encodeURIComponent(search)}&filter=${encodeURIComponent(filter)}`),items=await response.json();if(!response.ok)throw new Error(items.error||"No se pudieron cargar.");target.innerHTML=items.length?items.map(item=>`<button class="conversation-item ${item.unread_count?"unread":""}" data-conversation="${item.id}"><b>${safeUser(item.patient_name||item.patient_phone)}</b><small>${safeUser(item.patient_phone)} · ${new Date(item.last_message_at).toLocaleString("es-AR")}</small><span class="tag">${safeUser(item.category)}</span></button>`).join(""):'<p class="detail">No hay conversaciones todavía. Aparecerán cuando se conecte la Cloud API y lleguen mensajes.</p>';target.querySelectorAll("[data-conversation]").forEach(button=>button.onclick=()=>openConversation(button.dataset.conversation));}catch(error){target.innerHTML=`<p class="detail">${safeUser(error.message)}</p>`;} }
async function openConversation(id) { selectedConversationId=id;const response=await fetch(`${TRIAGE_API}/api/whatsapp/conversations/${encodeURIComponent(id)}/messages?token=${encodeURIComponent(connectionToken())}`),items=await response.json(),target=document.getElementById("chatMessages");target.innerHTML=response.ok&&items.length?items.map(item=>`<div class="chat-message ${item.direction}">${safeUser(item.body)}<small>${new Date(item.created_at).toLocaleString("es-AR")} · ${safeUser(item.delivery_status)}</small></div>`).join(""):'<p class="detail">Sin mensajes para mostrar.</p>'; }
async function sendChatMessage() { const input=document.getElementById("chatComposer"),message=input.value.trim();if(!selectedConversationId||!message)return alert("Elegí una conversación y escribí un mensaje.");const response=await fetch(`${TRIAGE_API}/api/whatsapp/conversations/${encodeURIComponent(selectedConversationId)}/messages?token=${encodeURIComponent(connectionToken())}`,{method:"POST",headers:{"content-type":"text/plain"},body:JSON.stringify({message})}),data=await response.json();if(!response.ok)return alert(data.error||"No se pudo enviar.");input.value="";openConversation(selectedConversationId); }
async function loadNotifications() { try{const response=await fetch(`${TRIAGE_API}/api/internal-notifications?token=${encodeURIComponent(connectionToken())}`),items=await response.json();if(!response.ok)return;const unread=items.filter(item=>!item.read_at);document.getElementById("notificationCount").textContent=unread.length;let panel=document.getElementById("notificationPanel");if(!panel){panel=document.createElement("div");panel.id="notificationPanel";panel.className="notification-panel";panel.hidden=true;document.querySelector(".top")?.append(panel);}panel.innerHTML=items.length?items.map(item=>`<div class="notification-item-panel ${item.read_at?"":"unread"}" data-notification="${item.id}"><b>${safeUser(item.title)}</b><div class="detail">${safeUser(item.message)}</div><small>${new Date(item.created_at).toLocaleString("es-AR")}</small></div>`).join(""):'<div class="notification-empty">No hay notificaciones.</div>';panel.querySelectorAll("[data-notification]").forEach(item=>item.onclick=()=>markNotificationRead(item.dataset.notification));}catch(_){} }
async function markNotificationRead(id){await fetch(`${TRIAGE_API}/api/internal-notifications/${encodeURIComponent(id)}/read?token=${encodeURIComponent(connectionToken())}`,{method:"PATCH"});loadNotifications();}

function directoryPayload(scope){
  const read=name=>scope.querySelector(`[data-directory-field="${name}"]`)?.value??document.getElementById(`directoryOwn${name[0].toUpperCase()}${name.slice(1)}`)?.value??'';
  const checked=name=>scope.querySelector(`[data-directory-field="${name}"]`)?.checked??document.getElementById(`directoryOwn${name[0].toUpperCase()}${name.slice(1)}`)?.checked??false;
  return {professionalName:read('name')||read('professionalName'),registrationNumber:read('registration'),specialty:read('specialty'),attentionType:read('attention'),clinicName:read('clinic'),province:read('province'),locality:read('locality'),postalCode:read('postal'),address:read('address'),latitude:read('latitude'),longitude:read('longitude'),phone:read('phone'),hours:read('hours'),services:read('services').split(',').map(x=>x.trim()).filter(Boolean),appointmentsEnabled:checked('appointments'),testEnabled:checked('test'),publicEnabled:checked('public'),publicationConsent:checked('consent')};
}
let triageProfilesCache=[];
function renderTriageDirectoryProfiles(){const target=document.getElementById('triageAdminProfiles'),query=(document.getElementById('triageDirectorySearch')?.value||'').trim().toLowerCase(),profiles=triageProfilesCache.filter(profile=>!query||`${profile.professional_name} ${profile.username} ${profile.clinic_name} ${profile.specialty} ${(profile.visibilityReasons||[]).join(' ')}`.toLowerCase().includes(query));target.innerHTML=profiles.length?profiles.map(profile=>directoryAdminCard(profile)).join(''):'<p class="detail">No hay profesionales que coincidan con la búsqueda.</p>';target.querySelectorAll('.saveDirectoryAdmin').forEach(button=>button.onclick=()=>saveDirectoryAdminProfile(button.closest('[data-directory-professional]')));}
async function loadTriageIntegration(){
  const target=document.getElementById('triageAdminProfiles');if(!target||activeProfessional().role!=='superadmin')return;
  try{const response=await fetch(`${TRIAGE_API}/api/directory/admin?token=${encodeURIComponent(connectionToken())}`),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo consultar la integración.');const metricIds={registered:'triageRegistered',active:'triageActive',published:'triagePublished',withoutLocation:'triageWithoutLocation',geolocationErrors:'triageGeoErrors',pendingPublication:'triagePendingPublication',requests:'triageRequests'};Object.entries(metricIds).forEach(([key,id])=>{const el=document.getElementById(id);if(el)el.textContent=data.metrics?.[key]??0});const dot=document.getElementById('triageConnectionDot');dot.className=`connection-dot ${data.connected?'connected':'error'}`;document.getElementById('triageConnectionStatus').textContent=data.connected?'Centro y Triage conectados':'Error de sincronización';document.getElementById('triageLastSync').textContent=`Última sincronización: ${data.settings?.last_successful_sync_at?new Date(data.settings.last_successful_sync_at).toLocaleString('es-AR'):'sin registro'}`;triageProfilesCache=data.profiles||[];renderTriageDirectoryProfiles();document.getElementById('triageIntegrationErrors').innerHTML=data.errors?.length?data.errors.map(error=>`<div>${safeUser(error.created_at)} · ${safeUser(error.event_type)} · ${safeUser(error.message)}</div>`).join(''):'Sin errores registrados.';}catch(error){target.innerHTML=`<p class="detail">${safeUser(error.message)}</p>`;document.getElementById('triageConnectionStatus').textContent='Sin conexión';document.getElementById('triageConnectionDot').className='connection-dot error';}
}
function directoryAdminCard(profile){const value=(field)=>safeUser(profile[field]??''),missing=profile.missing||[],reasons=profile.visibilityReasons||[];return `<article class="triage-profile-card" data-directory-professional="${value('professional_user_id')}"><div class="triage-profile-head"><div><h3>${value('professional_name')||'Profesional sin nombre'}</h3><p class="detail">@${value('username')} · ${value('clinic_name')} · ${value('email')}</p></div><div class="triage-statuses"><span class="tag ${profile.active&&profile.account_status==='active'?'':'wait'}">${profile.active&&profile.account_status==='active'?'Activo':'Inactivo'}</span><span class="tag ${profile.public_enabled?'':'wait'}">${profile.public_enabled?'Publicado en Triage':'No publicado'}</span><span class="tag ${profile.hasCoordinates?'':'wait'}">${profile.hasCoordinates?'Distancia disponible':'Sin coordenadas'}</span></div></div><div class="directory-diagnostic ${reasons.length?'warn':''}"><b>${reasons.length?'Por qué no aparece o no participa de todos los modos:':'Perfil disponible correctamente'}</b>${reasons.length?`<ul>${reasons.map(reason=>`<li>${safeUser(reason)}</li>`).join('')}</ul>`:'<p>Puede mostrarse en el directorio general y en búsquedas por distancia.</p>'}</div><div class="directory-editor-grid"><label>Nombre<input data-directory-field="professionalName" value="${value('professional_name')}"></label><label>Matrícula<input data-directory-field="registration" value="${value('registration_number')}"></label><label>Especialidad<input data-directory-field="specialty" value="${value('specialty')}"></label><label>Tipo de atención<input data-directory-field="attention" value="${value('attention_type')}"></label><label>Clínica<input data-directory-field="clinic" value="${value('clinic_name')}"></label><label>Provincia<input data-directory-field="province" value="${value('province')}"></label><label>Localidad<input data-directory-field="locality" value="${value('locality')}"></label><label>Código postal<input data-directory-field="postal" value="${value('postal_code')}"></label><label class="wide">Dirección profesional<input data-directory-field="address" value="${value('professional_address')}"></label><label>Latitud<input data-directory-field="latitude" value="${value('latitude')}"></label><label>Longitud<input data-directory-field="longitude" value="${value('longitude')}"></label><label>Teléfono público<input data-directory-field="phone" value="${value('public_phone')}"></label><label class="wide">Horarios<input data-directory-field="hours" value="${value('hours')}"></label><label class="wide">Servicios<input data-directory-field="services" value="${safeUser((profile.services||[]).join(', '))}"></label></div><div class="directory-consents"><label><input type="checkbox" data-directory-field="appointments" ${profile.appointments_enabled?'checked':''}> Recibir solicitudes</label><label><input type="checkbox" data-directory-field="test" ${profile.test_enabled?'checked':''}> Habilitar prueba protegida</label><label><input type="checkbox" data-directory-field="public" ${profile.public_enabled?'checked':''} ${profile.publication_consent_at?'':'disabled'}> Publicar en Triage</label></div><div class="billing-actions"><button class="primary saveDirectoryAdmin" type="button">Guardar configuración</button></div><p class="detail directory-card-message">${profile.public_enabled&&!profile.hasCoordinates?'Visible en “Ver todos”; completá coordenadas para “Cerca de mí”.':''}</p></article>`}
async function saveDirectoryAdminProfile(card){const message=card.querySelector('.directory-card-message'),payload=directoryPayload(card);message.textContent='Guardando…';const response=await fetch(`${TRIAGE_API}/api/directory/admin/professionals/${encodeURIComponent(card.dataset.directoryProfessional)}?token=${encodeURIComponent(connectionToken())}`,{method:'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify(payload)}),data=await response.json();message.textContent=response.ok?'Configuración guardada y auditada.':data.error||'No se pudo guardar.';if(response.ok)await loadTriageIntegration();}
async function rotateTriagePreview(){if(!confirm('Se invalidará el enlace de prueba anterior. ¿Generar uno nuevo?'))return;const response=await fetch(`${TRIAGE_API}/api/directory/admin/preview-token?token=${encodeURIComponent(connectionToken())}`,{method:'POST'}),data=await response.json();if(!response.ok)return alert(data.error||'No se pudo generar el acceso.');const link=document.getElementById('openTriagePreview');link.href=data.previewUrl;link.hidden=false;link.textContent='Abrir Triage protegido';await navigator.clipboard?.writeText(data.previewUrl).catch(()=>{});alert('Acceso protegido generado. El enlace quedó listo y se copió cuando el navegador lo permitió.');}
async function loadDirectoryOwnProfile(){const card=document.querySelector('.directory-own-profile');if(!card||activeProfessional().role!=='odontologo')return;card.hidden=false;try{const response=await fetch(`${TRIAGE_API}/api/directory/profile?token=${encodeURIComponent(connectionToken())}${supportSuffix()}`),profile=await response.json();if(!response.ok)throw new Error(profile.error||'No se pudo cargar el perfil.');const set=(id,value)=>{const el=document.getElementById(id);if(el)el.value=value??''};set('directoryOwnName',profile.professional_name);set('directoryOwnRegistration',profile.registration_number);set('directoryOwnSpecialty',profile.specialty);set('directoryOwnAttention',profile.attention_type);set('directoryOwnClinic',profile.clinic_name);set('directoryOwnProvince',profile.province);set('directoryOwnLocality',profile.locality);set('directoryOwnPostal',profile.postal_code);set('directoryOwnAddress',profile.professional_address);set('directoryOwnLatitude',profile.latitude);set('directoryOwnLongitude',profile.longitude);set('directoryOwnPhone',profile.public_phone);set('directoryOwnHours',profile.hours);set('directoryOwnServices',JSON.parse(profile.services_json||'[]').join(', '));document.getElementById('directoryOwnAppointments').checked=!!profile.appointments_enabled;document.getElementById('directoryOwnConsent').checked=!!profile.publication_consent_at;document.getElementById('directoryOwnMessage').textContent=profile.public_enabled?'Perfil publicado en Triage.':profile.publication_consent_at?'Perfil pendiente de aprobación del Superadmin.':'Perfil privado.';}catch(error){document.getElementById('directoryOwnMessage').textContent=error.message;}}
async function saveDirectoryOwnProfile(){const card=document.querySelector('.directory-own-profile'),message=document.getElementById('directoryOwnMessage'),payload=directoryPayload(card);message.textContent='Guardando…';const response=await fetch(`${TRIAGE_API}/api/directory/profile?token=${encodeURIComponent(connectionToken())}${supportSuffix()}`,{method:'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify(payload)}),data=await response.json();message.textContent=response.ok?(data.pendingApproval?'Perfil guardado. Quedó pendiente de aprobación del Superadmin.':'Perfil guardado.'):(data.error||'No se pudo guardar.');if(response.ok)await loadDirectoryOwnProfile();}

async function openPatientTimeline(id){const dialog=document.getElementById('patientTimelineDialog'),content=document.getElementById('patientTimelineContent');dialog.showModal();content.innerHTML='<p class="detail">Cargando ficha integrada…</p>';const response=await fetch(`${TRIAGE_API}/api/consultations/${encodeURIComponent(id)}/timeline?token=${encodeURIComponent(connectionToken())}${supportSuffix()}`),data=await response.json();if(!response.ok){content.innerHTML=`<p class="detail">${safeUser(data.error||'No se pudo abrir la ficha.')}</p>`;return}const r=data.record,p=r.patient||{},a=r.appointment||{};document.getElementById('patientTimelineTitle').textContent=p.name||'Paciente';content.innerHTML=`<div class="patient-timeline-grid"><article><small>Contacto</small><h3>${safeUser(p.name||'Paciente')}</h3><p>${safeUser(p.phone||'Sin teléfono')}<br>${safeUser(p.email||'Sin correo')}</p></article><article><small>Solicitud actual</small><h3>${safeUser(r.status)}</h3><p>${safeUser(r.intake?.reason||'Sin motivo')}<br>${safeUser(r.id)}</p></article><article><small>Turno</small><h3>${safeUser(a.date||'Sin fecha')} ${safeUser(a.time||'')}</h3><p>${safeUser(r.professional?.selected_professional_name||'Profesional del consultorio')}</p></article></div><div class="billing-actions" style="margin-top:18px"><button class="primary patientAction" data-status="turno_confirmado">Aceptar / confirmar</button><button class="secondary patientReschedule">Reprogramar</button><button class="danger-action patientAction" data-status="rechazado">Rechazar</button></div><div class="patient-timeline-list"><h3>Historial del paciente</h3>${(data.related||[]).map(item=>`<article><b>${safeUser(item.status)}</b><div class="detail">${safeUser(item.appointment?.date||'Sin turno')} ${safeUser(item.appointment?.time||'')} · ${new Date(item.created_at).toLocaleString('es-AR')}</div></article>`).join('')||'<p class="detail">Sin antecedentes adicionales.</p>'}<h3>Auditoría y comunicaciones</h3>${(data.audit||[]).map(item=>`<article><b>${safeUser(item.event_type)}</b><div class="detail">${new Date(item.created_at).toLocaleString('es-AR')} · ${safeUser(item.actor_type)}</div></article>`).join('')||'<p class="detail">Sin movimientos.</p>'}</div>`;content.querySelectorAll('.patientAction').forEach(button=>button.onclick=()=>updateTriageRequest(r,button.dataset.status));content.querySelector('.patientReschedule').onclick=()=>rescheduleTriageRequest(r);}
async function updateTriageRequest(record,status,appointment=record.appointment){if(status==='turno_confirmado'&&(!appointment?.date||!appointment?.time))return rescheduleTriageRequest(record,true);const response=await fetch(`${TRIAGE_API}/api/consultations/${encodeURIComponent(record.id)}?token=${encodeURIComponent(connectionToken())}${supportSuffix()}`,{method:'PATCH',headers:{'content-type':'text/plain'},body:JSON.stringify({status,appointment})}),data=await response.json();if(!response.ok)return alert(data.error||'No se pudo actualizar.');document.getElementById('patientTimelineDialog').close();await syncTriage(true);}
function rescheduleTriageRequest(record,confirmAfter=false){const date=prompt('Nueva fecha (AAAA-MM-DD):',record.appointment?.date||''),time=date&&prompt('Nuevo horario (HH:MM):',record.appointment?.time||'');if(!date||!time)return;updateTriageRequest(record,confirmAfter?'turno_confirmado':'turno_solicitado',{...record.appointment,date,time,status:confirmAfter?'confirmado':'solicitado'});}

async function syncTriage(silent = false) {
  const token = connectionToken();
  if (!token) return connectTriage();
  setConnectionLabel("Sincronizando…");
  try {
    const [response,queueResponse] = await Promise.all([fetch(`${TRIAGE_API}/api/integrated/consultations?token=${encodeURIComponent(token)}${supportSuffix()}`),fetch(`${TRIAGE_API}/api/integrated/capacity-queue?token=${encodeURIComponent(token)}${supportSuffix()}`)]);
    const records = await response.json(), capacityQueue=queueResponse.ok?await queueResponse.json():[];
    if (!response.ok) throw new Error(records.error || "Sesión vencida");
    renderLiveData(records,capacityQueue);
    setConnectionLabel(`✓ ${records.length} en Triage${capacityQueue.length?` · ${capacityQueue.length} pendientes por cupo`:''}`);
  } catch (error) {
    sessionStorage.removeItem("odontocentroTriageToken");
    setConnectionLabel("↻ Triage");
    if (!silent) alert(`No se pudo sincronizar: ${error.message}`);
  }
}

function renderLiveData(records,capacityQueue=[]) {
  const safe = value => String(value ?? "").replace(/[&<>\"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
  const today = new Date().toISOString().slice(0, 10);
  const appointments = records.filter(r => r.appointment?.date && r.appointment?.time);
  const todayAppointments = appointments.filter(r => r.appointment.date === today);
  const pending = records.filter(r => ["recibido", "nueva", "turno_solicitado", "requiere_turno"].includes(r.status));
  const hero = document.querySelector("#dashboard .hero p");
  if (hero) hero.innerHTML = records.length ? `Sincronizado con Triage: <strong>${records.length} fichas reales</strong>, ${appointments.length} turnos y ${pending.length} casos pendientes.` : "Conectado a Triage. Todavía no hay fichas ni turnos reales cargados para mostrar.";
  const metrics = document.querySelectorAll("#dashboard .grid .num");
  if (metrics[0]) metrics[0].textContent = todayAppointments.length;
  if (metrics[1]) metrics[1].textContent = records.length;
  if (metrics[3]) metrics[3].textContent = pending.length;
  const agenda = document.querySelector("#dashboard .content article:first-child");
  if (agenda) {
    const next = appointments.filter(r => r.appointment.date >= today).sort((a,b) => `${a.appointment.date}${a.appointment.time}`.localeCompare(`${b.appointment.date}${b.appointment.time}`)).slice(0, 5);
    agenda.innerHTML = `<h2 class="section-title">Agenda sincronizada <span class="sub">Datos de Triage</span></h2>${next.length ? next.map(r => `<div class="agenda-row"><span class="time">${r.appointment.time}</span><div><span class="person">${r.patient?.name || "Paciente"}</span><div class="detail">${r.intake?.reason || r.appointment.area || "Atención odontológica"}</div></div><span class="tag ${r.status === "turno_confirmado" ? "" : "wait"}">${r.status === "turno_confirmado" ? "Confirmado" : "Pendiente"}</span></div>`).join("") : "<p class='detail'>No hay turnos próximos en Triage.</p>"}`;
  }
  const agendaPage = document.querySelector("#agenda .card");
  if (agendaPage) {
    const ordered = [...appointments].sort((a,b) => `${a.appointment.date}${a.appointment.time}`.localeCompare(`${b.appointment.date}${b.appointment.time}`));
    agendaPage.innerHTML = `<h2 class="section-title">Agenda clínica <span class="sub">Sincronización automática · cada 5 segundos</span></h2><div class="toolbar"><input class="search" placeholder="Buscar paciente o profesional"><button class="primary" id="agendaNew">+ Agendar paciente</button></div>${ordered.length ? ordered.map(r => `<div class="agenda-row"><span class="time">${safe(r.appointment.time)}</span><div><span class="person">${safe(r.patient?.name || "Paciente")}</span><div class="detail">${safe(r.intake?.reason || r.appointment?.area || "Atención odontológica")} · ${safe(r.appointment.date)} · Origen: ${safe(({web:"Web",whatsapp:"WhatsApp",manual:"Carga manual",phone:"Teléfono",in_person:"Presencial"})[r.appointment?.origin]||"Web")}</div></div><span class="tag ${r.status === "turno_confirmado" ? "" : "wait"}">${r.status === "turno_confirmado" ? "Confirmado" : "Pendiente"}</span></div>`).join("") : "<p class='detail'>Todavía no hay turnos registrados desde la web.</p>"}`;
  }
  const patientBody = document.querySelector("#patients tbody");
  const patientTotal = document.querySelector("#patients .section-title .sub");
  const triageRequestList=document.getElementById('triageRequestList');
  if(triageRequestList){const queued=capacityQueue.map(r=>`<article class="triage-request-item capacity-pending"><div><b>${safe(r.patient?.name||'Paciente')}</b><div class="detail">${safe(r.intake?.reason||'Consulta odontológica')}<br>${safe(r.patient?.phone||'Sin teléfono')} · ${safe(r.id)}</div></div><div class="triage-request-actions"><span class="tag wait">Pendiente por cupo</span><small class="detail">Solicitud preservada; todavía no creó ficha</small></div></article>`).join(''),active=records.map(r=>`<article class="triage-request-item"><div><b>${safe(r.patient?.name||'Paciente')}</b><div class="detail">${safe(r.intake?.reason||'Consulta odontológica')} · ${safe(r.professional?.selected_professional_name||'Profesional del consultorio')}<br>${safe(r.patient?.phone||'Sin teléfono')} · ${safe(r.id)}</div></div><div class="triage-request-actions"><span class="tag ${r.status==='turno_confirmado'?'':'wait'}">${safe(r.status)}</span><button class="secondary openPatientTimeline" data-consultation="${safe(r.id)}" type="button">Abrir ficha</button></div></article>`).join('');triageRequestList.innerHTML=queued+active||'<p class="detail">Todavía no llegaron solicitudes desde Triage.</p>'}
  if (patientTotal) patientTotal.textContent = `${records.length} historias sincronizadas`;
  if (patientBody) patientBody.innerHTML = records.length ? records.map(r => `<tr><td>${safe(r.patient?.name || "Paciente")}<br><span class="detail">${safe(r.patient?.phone || "Sin teléfono")} · ${safe(r.id || "")}</span></td><td>A informar</td><td>${safe(r.updated_at ? new Date(r.updated_at).toLocaleDateString("es-AR") : "—")}</td><td class="money">$ 0</td><td><span class="tag ${r.status === "turno_confirmado" ? "" : "wait"}">${r.status === "turno_confirmado" ? "Confirmado" : "En gestión"}</span><br><button class="secondary openPatientTimeline" data-consultation="${safe(r.id)}" type="button">Abrir ficha</button></td></tr>`).join("") : "<tr><td colspan='5' class='detail'>Todavía no hay pacientes sincronizados desde Triage.</td></tr>";
  document.querySelectorAll('.openPatientTimeline').forEach(button=>button.onclick=()=>openPatientTimeline(button.dataset.consultation));
}

