document.getElementById("openAppearance")?.addEventListener("click",openAppearanceDialog);
document.getElementById("closeAppearance")?.addEventListener("click",closeAppearanceDialog);
document.getElementById("appearanceDialog")?.addEventListener("click",event=>{if(event.target.id==="appearanceDialog")closeAppearanceDialog()});
document.querySelectorAll("[data-theme-choice]").forEach(button=>button.addEventListener("click",()=>saveThemePreference(button.dataset.themeChoice)));
document.addEventListener("keydown",event=>{if(event.key==="Escape"){closeAppearanceDialog();closeClinicDialog()}});
document.querySelectorAll("#chatQuickActions button").forEach(button=>button.addEventListener("click",()=>alert(`${button.textContent}: acción preparada para vincular la conversación con la agenda y registrar auditoría.`)));
document.getElementById("logoutButton")?.addEventListener("click", logoutProfessional);
async function resumeProfessionalSession() {
  const token = connectionToken();
  if (!token) return openLoginScreen();
  try {
    const response = await fetch(`${TRIAGE_API}/api/professional/session?token=${encodeURIComponent(token)}`), data = await response.json();
    if (!response.ok || !data.user) throw new Error("Sesión vencida");
    sessionStorage.setItem("odontocentroProfessional", JSON.stringify(data.user));
    sessionStorage.setItem("odontocentroUsername", data.user.username || "");
    renderProfessional(data.user);
    if(data.user.role==='superadmin') await loadSaasWorkspace(); else await Promise.all([syncTriage(true), loadPracticePlan()]);
  } catch (_) {
    sessionStorage.removeItem("odontocentroTriageToken");
    sessionStorage.removeItem("odontocentroProfessional");
    openLoginScreen();
  }
}
resumeProfessionalSession();
setInterval(()=>{if(activeProfessional()?.role==='superadmin')loadExchangeRates()},300000);
setInterval(() => { if (document.visibilityState === "visible" && connectionToken()) syncTriage(true); }, 5000);
